// Smoke-test realm for the Gnome Tavern hackathon.
// A minimal persistent counter, written from scratch.
// Deployed to the Onyx testnet as
// gno.land/r/g1ssyj4q3mlj4z8v0hfyauvkj6m97m7n2vem793m/counter.
package counter

import "strconv"

// count is the persistent counter value, stored on-chain in realm state.
var count int

// Increment raises the counter by one and returns the new value.
// The `_ realm` parameter makes this a crossing function: called from
// another realm (or a transaction via gnokey) it switches scope into
// this realm, which is what allows it to update the realm's state.
func Increment(_ realm) int {
	count++
	return count
}

// GetCount returns the current counter value.
func GetCount() int {
	return count
}

// Render renders the realm as a web page.
func Render(path string) string {
	return "# Smoke Test Counter\n\n" +
		"Current count: " + strconv.Itoa(count) + "\n\n" +
		"Call `Increment()` to raise the count by one.\n"
}

package counter

import "testing"

func TestIncrement(cur realm, t *testing.T) {
	before := GetCount()
	val := Increment(cross(cur))
	if val != before+1 {
		t.Fatalf("after Increment: got %d, want %d", val, before+1)
	}
	if got := GetCount(); got != before+1 {
		t.Fatalf("GetCount after Increment: got %d, want %d", got, before+1)
	}
	val = Increment(cross(cur))
	if val != before+2 {
		t.Fatalf("after 2nd Increment: got %d, want %d", val, before+2)
	}
}

func TestRenderShowsCount(t *testing.T) {
	rendered := Render("")
	if rendered == "" {
		t.Fatal("Render returned empty string")
	}
	// Render must contain the current count as text.
	want := "Current count: " + itoa(GetCount())
	if !contains(rendered, want) {
		t.Fatalf("Render() = %q, want it to contain %q", rendered, want)
	}
}

// itoa converts a small non-negative int to decimal without strconv,
// so the test does not depend on the same helper the realm uses.
func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	digits := []byte{}
	for n > 0 {
		digits = append([]byte{byte('0' + n%10)}, digits...)
		n /= 10
	}
	return string(digits)
}

func contains(s, sub string) bool {
	if len(sub) == 0 {
		return true
	}
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return true
		}
	}
	return false
}

// Package check is a small test harness that runs inside a transaction.
//
// Go's testing package only runs under `gno test`. Assertpay needs the
// same idea on chain: a spec's tests run against a submitted implementation
// while a realm call is executing, and every result is kept. Each test runs
// under recover, so a panic in the implementation (declared in a /p/
// package) fails that one test instead of aborting the transaction.
package check

import "strconv"

// T is handed to each test.
type T struct {
	failed bool
	msg    string
}

type stop struct{}

// Fatal fails the test with msg and stops it.
func (t *T) Fatal(msg string) {
	t.failed = true
	t.msg = msg
	panic(stop{})
}

// Check fails the test with msg if ok is false.
func (t *T) Check(ok bool, msg string) {
	if !ok {
		t.Fatal(msg)
	}
}

// Test is one named check.
type Test struct {
	Name string
	Fn   func(t *T)
}

// Result is the outcome of one test.
type Result struct {
	Name string
	Pass bool
	Msg  string
}

// Spec describes a spec package to the Assertpay realm.
type Spec struct {
	Name string // short id, e.g. "intervals"
	Doc  string // one paragraph for humans
	// Tests builds the tests for an implementation and a seed. impl is
	// whatever the solver submitted; a spec must turn a wrong type into a
	// failing test, never a panic.
	Tests func(impl any, seed uint64) []Test
}

// Run runs every test and returns the results in order.
func Run(tests []Test) []Result {
	out := make([]Result, 0, len(tests))
	for _, tc := range tests {
		out = append(out, runOne(tc))
	}
	return out
}

// RunSpec builds and runs a spec's tests for impl and seed.
func RunSpec(s Spec, impl any, seed uint64) []Result {
	var tests []Test
	func() {
		defer func() {
			if recover() != nil {
				tests = []Test{{Name: "Build", Fn: func(t *T) { t.Fatal("the spec could not build tests for this implementation") }}}
			}
		}()
		tests = s.Tests(impl, seed)
	}()
	return Run(tests)
}

func runOne(tc Test) (r Result) {
	r.Name = tc.Name
	t := &T{}
	defer func() {
		if e := recover(); e != nil {
			if _, ok := e.(stop); !ok {
				t.failed = true
				t.msg = "implementation panicked: " + panicText(e)
			}
		}
		r.Pass = !t.failed
		r.Msg = t.msg
	}()
	tc.Fn(t)
	return
}

func panicText(e any) string {
	switch v := e.(type) {
	case string:
		return v
	case error:
		return v.Error()
	}
	return "non-string panic"
}

// Passed counts passing results.
func Passed(rs []Result) int {
	n := 0
	for _, r := range rs {
		if r.Pass {
			n++
		}
	}
	return n
}

// FirstFailure returns the first failing result, if any.
func FirstFailure(rs []Result) (Result, bool) {
	for _, r := range rs {
		if !r.Pass {
			return r, true
		}
	}
	return Result{}, false
}

// Rand is a small deterministic generator (xorshift64*).
type Rand struct{ s uint64 }

// NewRand returns a generator for seed (0 is remapped).
func NewRand(seed uint64) *Rand {
	if seed == 0 {
		seed = 0x9e3779b97f4a7c15
	}
	return &Rand{s: seed}
}

// Next returns the next 64-bit value.
func (r *Rand) Next() uint64 {
	r.s ^= r.s >> 12
	r.s ^= r.s << 25
	r.s ^= r.s >> 27
	return r.s * 2685821657736338717
}

// Intn returns a value in [0, n).
func (r *Rand) Intn(n int) int {
	if n <= 0 {
		return 0
	}
	return int(r.Next() % uint64(n))
}

// Sub derives an independent seed for case i, so each generated case can be
// reproduced on its own.
func Sub(seed uint64, i int) uint64 {
	r := NewRand(seed ^ (uint64(i+1) * 0x9e3779b97f4a7c15))
	r.Next()
	return r.Next()
}

// Itoa is strconv.Itoa, re-exported for spec messages.
func Itoa(n int) string { return strconv.Itoa(n) }

// Package market is Assertpay's task state machine, kept pure: it takes
// heights, addresses and amounts as arguments and returns the payments to
// make. The realm owns the coins and decides who may call what and when.
//
// A task is funded on a spec. Solvers commit a hash with a bond, then
// reveal an implementation whose test results the realm passes in. Passing
// attempts are ordered by commit height; the earliest one not removed is
// the winner. During the window anyone may challenge the winner with a
// seed of their choice; a failure removes it and pays its bond to the
// challenger. After the window the winner can be paid.
package market

import "errors"

// Parameters, in blocks and ugnot.
const (
	Expiry      = 600       // a commit must be revealed within this many blocks
	Window      = 120       // challenge window after a new winner
	Grace       = 60        // blocks to complete an opened challenge
	MinBond     = 1_000_000 // 1 GNOT
	BondDivisor = 10        // bond = max(MinBond, reward / BondDivisor)
	MinReward   = 1_000_000
	MinDeadline = 200
	MaxDeadline = 200_000
)

var (
	ErrClosed       = errors.New("task is closed")
	ErrDeadline     = errors.New("commits are closed: the deadline has passed")
	ErrLiveCommit   = errors.New("you already have a live commit on this task")
	ErrNoCommit     = errors.New("no live commit matches this reveal")
	ErrNoWinner     = errors.New("no winner to challenge")
	ErrWindowOver   = errors.New("the challenge window is over")
	ErrOpenChal     = errors.New("a challenge is already open")
	ErrNoOpenChal   = errors.New("no open challenge")
	ErrGraceRunning = errors.New("the challenge can still be run")
	ErrNotClaimable = errors.New("not claimable yet")
	ErrNotRefund    = errors.New("not refundable: deadline not passed, or a winner, live commit or challenge exists")
	ErrBadParams    = errors.New("bad parameters")
)

// State of a task.
const (
	Open     = "open"
	Paid     = "paid"
	Refunded = "refunded"
)

// Payment is a transfer the realm must make.
type Payment struct {
	To     address
	Amount int64
	Why    string
}

// Commit is a sealed promise to reveal.
type Commit struct {
	Hash      string
	Who       address
	Height    int64
	Revealed  bool
	Forfeited bool
}

// Attempt is one revealed implementation and its results.
type Attempt struct {
	ID       int
	Who      address
	Entry    string // realm that revealed it
	CommitH  int64
	Height   int64
	Seed     uint64
	Passed   int
	Total    int
	Fail     string // first failure, "Name: message"
	Bits     string // one char per test, 'p' or 'f'
	Removed  bool   // knocked out by a challenge
	BondHeld bool   // bond locked because it passed
	Impl     any    // what was submitted, kept for challenges
}

// Challenge is a recorded challenge of the winner.
type Challenge struct {
	Who     address
	Target  int // attempt id
	Seed    uint64
	Height  int64
	Bond    int64 // only for the open (two-phase) kind
	Open    bool
	Outcome string // "held", "broke", "timeout"
	Fail    string
	Bits    string
}

// Task is one funded spec.
type Task struct {
	ID         int
	Spec       string
	Sponsor    address
	Reward     int64
	Bond       int64
	Created    int64
	Deadline   int64
	State      string
	Commits    []*Commit
	Attempts   []*Attempt
	Challenges []*Challenge
	WinnerID   int // -1 when none
	WindowEnd  int64
	Forfeit    int64 // expired bonds (kept out of the reward)
}

// NewTask validates and opens a task.
func NewTask(id int, spec string, sponsor address, reward int64, now, deadlineBlocks int64) *Task {
	if reward < MinReward || deadlineBlocks < MinDeadline || deadlineBlocks > MaxDeadline || spec == "" {
		panic(ErrBadParams)
	}
	bond := reward / BondDivisor
	if bond < MinBond {
		bond = MinBond
	}
	return &Task{ID: id, Spec: spec, Sponsor: sponsor, Reward: reward, Bond: bond, Created: now, Deadline: now + deadlineBlocks, State: Open, WinnerID: -1}
}

func (t *Task) mustOpen() {
	if t.State != Open {
		panic(ErrClosed)
	}
}

// Live reports whether a commit can still be revealed at now.
func (c *Commit) Live(now int64) bool {
	return !c.Revealed && !c.Forfeited && now-c.Height <= Expiry
}

// Sweep forfeits expired commits and returns how much bond moved to the
// forfeit pool. Every state change calls it first.
func (t *Task) Sweep(now int64) int64 {
	var moved int64
	for _, c := range t.Commits {
		if !c.Revealed && !c.Forfeited && now-c.Height > Expiry {
			c.Forfeited = true
			t.Forfeit += t.Bond
			moved += t.Bond
		}
	}
	return moved
}

// AddCommit records a commit; the caller has already received the bond.
func (t *Task) AddCommit(who address, hash string, now int64) {
	t.mustOpen()
	t.Sweep(now)
	if now > t.Deadline {
		panic(ErrDeadline)
	}
	for _, c := range t.Commits {
		if c.Who == who && c.Live(now) {
			panic(ErrLiveCommit)
		}
	}
	t.Commits = append(t.Commits, &Commit{Hash: hash, Who: who, Height: now})
}

// FindCommit returns the live commit with hash by who.
func (t *Task) FindCommit(who address, hash string, now int64) *Commit {
	t.mustOpen()
	t.Sweep(now)
	for _, c := range t.Commits {
		if c.Hash == hash && c.Who == who && c.Live(now) {
			return c
		}
	}
	panic(ErrNoCommit)
}

// Result summarises a test run for the market.
type Result struct {
	Seed   uint64
	Passed int
	Total  int
	Fail   string
	Bits   string
}

// Pass reports whether every test passed.
func (r Result) Pass() bool { return r.Total > 0 && r.Passed == r.Total }

// Reveal records an attempt for commit c. A failing attempt gets its bond
// back now; a passing one keeps it locked and may become the winner.
func (t *Task) Reveal(c *Commit, entry string, impl any, res Result, now int64) (*Attempt, []Payment) {
	c.Revealed = true
	a := &Attempt{ID: len(t.Attempts), Who: c.Who, Entry: entry, CommitH: c.Height, Height: now, Seed: res.Seed,
		Passed: res.Passed, Total: res.Total, Fail: res.Fail, Bits: res.Bits, Impl: impl}
	t.Attempts = append(t.Attempts, a)
	if !res.Pass() {
		return a, []Payment{{To: c.Who, Amount: t.Bond, Why: "bond back: attempt failed"}}
	}
	a.BondHeld = true
	t.elect(now)
	return a, nil
}

// elect picks the earliest-committed passing attempt not removed and
// restarts the window if the winner changed.
func (t *Task) elect(now int64) {
	best := -1
	for _, a := range t.Attempts {
		if !a.BondHeld || a.Removed {
			continue
		}
		if best < 0 || a.CommitH < t.Attempts[best].CommitH || (a.CommitH == t.Attempts[best].CommitH && a.ID < best) {
			best = a.ID
		}
	}
	if best != t.WinnerID {
		t.WinnerID = best
		if best >= 0 {
			t.WindowEnd = now + Window
		}
	}
}

// Winner returns the current winner or nil.
func (t *Task) Winner() *Attempt {
	if t.WinnerID < 0 {
		return nil
	}
	return t.Attempts[t.WinnerID]
}

// OpenChallenge returns the open two-phase challenge, if any.
func (t *Task) OpenChallenge() *Challenge {
	for _, c := range t.Challenges {
		if c.Open {
			return c
		}
	}
	return nil
}

func (t *Task) mustChallengeable(now int64) *Attempt {
	t.mustOpen()
	w := t.Winner()
	if w == nil {
		panic(ErrNoWinner)
	}
	if now > t.WindowEnd {
		panic(ErrWindowOver)
	}
	if t.OpenChallenge() != nil {
		panic(ErrOpenChal)
	}
	return w
}

// CheckChallenge validates a one-shot challenge before the realm runs it.
func (t *Task) CheckChallenge(now int64) *Attempt { return t.mustChallengeable(now) }

// Challenged records a one-shot challenge result. A failure removes the
// winner and pays its bond to the challenger.
func (t *Task) Challenged(who address, res Result, now int64) []Payment {
	w := t.mustChallengeable(now)
	ch := &Challenge{Who: who, Target: w.ID, Seed: res.Seed, Height: now, Fail: res.Fail, Bits: res.Bits}
	t.Challenges = append(t.Challenges, ch)
	if res.Pass() {
		ch.Outcome = "held"
		return nil
	}
	ch.Outcome = "broke"
	return t.knockOut(w, who, 0, now)
}

func (t *Task) knockOut(w *Attempt, challenger address, extra int64, now int64) []Payment {
	w.Removed = true
	w.BondHeld = false
	t.elect(now)
	return []Payment{{To: challenger, Amount: t.Bond + extra, Why: "challenge broke the winner"}}
}

// Open starts a two-phase challenge (for winners whose code aborts the
// transaction). The caller has received bond from the challenger.
func (t *Task) Open(who address, seed uint64, bond int64, now int64) *Challenge {
	w := t.mustChallengeable(now)
	if bond < t.Bond {
		panic(ErrBadParams)
	}
	ch := &Challenge{Who: who, Target: w.ID, Seed: seed, Height: now, Bond: bond, Open: true}
	t.Challenges = append(t.Challenges, ch)
	return ch
}

// RanOpen records the run of the open challenge.
func (t *Task) RanOpen(res Result, now int64) []Payment {
	ch := t.OpenChallenge()
	if ch == nil {
		panic(ErrNoOpenChal)
	}
	ch.Open = false
	ch.Fail, ch.Bits = res.Fail, res.Bits
	w := t.Attempts[ch.Target]
	if res.Pass() {
		ch.Outcome = "held"
		return []Payment{{To: w.Who, Amount: ch.Bond, Why: "challenger bond: winner held"}}
	}
	ch.Outcome = "broke"
	return t.knockOut(w, ch.Who, ch.Bond, now)
}

// TimeoutOpen resolves an open challenge that nobody could run in Grace
// blocks: the winner is removed.
func (t *Task) TimeoutOpen(now int64) []Payment {
	ch := t.OpenChallenge()
	if ch == nil {
		panic(ErrNoOpenChal)
	}
	if now-ch.Height <= Grace {
		panic(ErrGraceRunning)
	}
	ch.Open = false
	ch.Outcome = "timeout"
	return t.knockOut(t.Attempts[ch.Target], ch.Who, ch.Bond, now)
}

// Claim pays the winner after the window.
func (t *Task) Claim(now int64) []Payment {
	t.mustOpen()
	t.Sweep(now)
	w := t.Winner()
	if w == nil || now <= t.WindowEnd || t.OpenChallenge() != nil {
		panic(ErrNotClaimable)
	}
	t.State = Paid
	w.BondHeld = false
	pays := []Payment{{To: w.Who, Amount: t.Reward + t.Bond, Why: "reward and bond"}}
	// other passing attempts get their bonds back
	for _, a := range t.Attempts {
		if a.BondHeld {
			a.BondHeld = false
			pays = append(pays, Payment{To: a.Who, Amount: t.Bond, Why: "bond back: task closed"})
		}
	}
	return pays
}

// Refund returns the reward after the deadline when nothing is pending.
func (t *Task) Refund(now int64) []Payment {
	t.mustOpen()
	t.Sweep(now)
	if now <= t.Deadline || t.Winner() != nil || t.OpenChallenge() != nil {
		panic(ErrNotRefund)
	}
	for _, c := range t.Commits {
		if c.Live(now) {
			panic(ErrNotRefund)
		}
	}
	t.State = Refunded
	return []Payment{{To: t.Sponsor, Amount: t.Reward, Why: "refund: no passing implementation"}}
}

// Package intervals is an Assertpay spec: a set of integers stored as
// half-open intervals.
//
// An implementation provides a Factory. Every test builds a fresh Set,
// applies a sequence of operations and compares the result with a simple
// bitmap model. Fixed examples come first; then Cases generated cases from
// the seed, each reproducible on its own with check.Sub(seed, i).
package intervals

import (
	"gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/aprh1/check/v1"
)

// Set is the interface a solver implements.
type Set interface {
	// Add inserts every x with lo <= x < hi. lo >= hi is a no-op.
	Add(lo, hi int)
	// Remove deletes every x with lo <= x < hi. lo >= hi is a no-op.
	Remove(lo, hi int)
	// Contains reports whether x is in the set.
	Contains(x int) bool
	// Spans returns the set as sorted, disjoint, non-touching half-open
	// intervals: [lo, hi) pairs where each hi < the next lo.
	Spans() [][2]int
}

// Factory builds an empty Set.
type Factory func() Set

const (
	// Cases is the number of generated cases per seed.
	Cases = 16
	// Universe bounds generated values to [0, Universe).
	Universe = 48
	// Ops is the number of operations per generated case.
	Ops = 12
)

// Spec describes this spec to Assertpay.
func Spec() check.Spec {
	return check.Spec{
		Name:  "intervals",
		Doc:   "An integer set stored as half-open intervals: Add, Remove, Contains and Spans (sorted, disjoint, merged). Checked against a bitmap model.",
		Tests: Tests,
	}
}

type op struct {
	add    bool
	lo, hi int
}

// Tests builds the tests for impl (a Factory or a func() Set).
func Tests(impl any, seed uint64) []check.Test {
	f, ok := asFactory(impl)
	if !ok {
		return []check.Test{{Name: "Type", Fn: func(t *check.T) { t.Fatal("implementation is not an intervals.Factory") }}}
	}
	tests := []check.Test{
		{"AddOne", run(f, []op{{true, 2, 5}})},
		{"MergeOverlap", run(f, []op{{true, 1, 4}, {true, 3, 8}})},
		{"RemoveMiddle", run(f, []op{{true, 0, 10}, {false, 4, 6}})},
		{"EmptyRange", run(f, []op{{true, 5, 5}, {true, 7, 3}})},
	}
	for i := 0; i < Cases; i++ {
		tests = append(tests, check.Test{Name: "Case" + check.Itoa(i), Fn: run(f, gen(check.Sub(seed, i)))})
	}
	return tests
}

func asFactory(impl any) (Factory, bool) {
	switch v := impl.(type) {
	case Factory:
		return v, v != nil
	case func() Set:
		return Factory(v), v != nil
	}
	return nil, false
}

func gen(seed uint64) []op {
	r := check.NewRand(seed)
	ops := make([]op, Ops)
	for i := range ops {
		lo := r.Intn(Universe)
		ops[i] = op{add: r.Intn(3) != 0, lo: lo, hi: lo + 1 + r.Intn(8)}
	}
	return ops
}

// run applies ops to a fresh Set and to the model, then compares.
func run(f Factory, ops []op) func(t *check.T) {
	return func(t *check.T) {
		s := f()
		var model [Universe + 16]bool
		for _, o := range ops {
			if o.add {
				s.Add(o.lo, o.hi)
			} else {
				s.Remove(o.lo, o.hi)
			}
			for x := o.lo; x < o.hi && x < len(model); x++ {
				model[x] = o.add
			}
		}
		for x := 0; x < len(model); x++ {
			if s.Contains(x) != model[x] {
				t.Fatal("after " + describe(ops) + ": Contains(" + check.Itoa(x) + ") = " + boolText(!model[x]))
			}
		}
		want := spansOf(model[:])
		got := s.Spans()
		if !equal(got, want) {
			t.Fatal("after " + describe(ops) + ": Spans() = " + spansText(got) + ", want " + spansText(want))
		}
	}
}

func spansOf(m []bool) [][2]int {
	var out [][2]int
	for x := 0; x < len(m); x++ {
		if m[x] && (x == 0 || !m[x-1]) {
			out = append(out, [2]int{x, x})
		}
		if m[x] && (x == len(m)-1 || !m[x+1]) {
			out[len(out)-1][1] = x + 1
		}
	}
	return out
}

func equal(a, b [][2]int) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func describe(ops []op) string {
	s := ""
	for i, o := range ops {
		if i > 0 {
			s += " "
		}
		if o.add {
			s += "+"
		} else {
			s += "-"
		}
		s += "[" + check.Itoa(o.lo) + "," + check.Itoa(o.hi) + ")"
	}
	return s
}

func spansText(sp [][2]int) string {
	s := "{"
	for i, p := range sp {
		if i > 0 {
			s += " "
		}
		s += "[" + check.Itoa(p[0]) + "," + check.Itoa(p[1]) + ")"
	}
	return s + "}"
}

func boolText(b bool) string {
	if b {
		return "true"
	}
	return "false"
}

// Package bad is a plausible but wrong intervals implementation: Add does
// not merge intervals that only touch, so Spans can return [1,3) [3,5)
// instead of [1,5). The fixed examples miss it; generated cases catch it.
package bad

import "gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/aprh1/specs/intervals/v1"

type set struct{ sp [][2]int }

// New returns an empty set.
func New() intervals.Set { return &set{} }

func (s *set) Add(lo, hi int) {
	if lo >= hi {
		return
	}
	var out [][2]int
	placed := false
	for _, p := range s.sp {
		switch {
		case p[1] <= lo:
			out = append(out, p)
		case p[0] >= hi:
			if !placed {
				out = append(out, [2]int{lo, hi})
				placed = true
			}
			out = append(out, p)
		default:
			if p[0] < lo {
				lo = p[0]
			}
			if p[1] > hi {
				hi = p[1]
			}
		}
	}
	if !placed {
		out = append(out, [2]int{lo, hi})
	}
	s.sp = out
}

func (s *set) Remove(lo, hi int) {
	if lo >= hi {
		return
	}
	var out [][2]int
	for _, p := range s.sp {
		if p[1] <= lo || p[0] >= hi {
			out = append(out, p)
			continue
		}
		if p[0] < lo {
			out = append(out, [2]int{p[0], lo})
		}
		if p[1] > hi {
			out = append(out, [2]int{hi, p[1]})
		}
	}
	s.sp = out
}

func (s *set) Contains(x int) bool {
	for _, p := range s.sp {
		if x >= p[0] && x < p[1] {
			return true
		}
	}
	return false
}

func (s *set) Spans() [][2]int {
	out := make([][2]int, len(s.sp))
	copy(out, s.sp)
	return out
}

// Package lru is an Assertpay spec: a fixed-capacity least-recently-used
// cache from string keys to ints.
//
// Every test builds a fresh cache with a capacity, applies a sequence of
// Get and Put calls and compares each answer with a slice model ordered by
// recency. Fixed examples come first; then Cases generated cases from the
// seed, each reproducible with check.Sub(seed, i).
package lru

import "gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/aprh1/check/v1"

// Cache is the interface a solver implements.
type Cache interface {
	// Get returns the value for key and marks key as most recently used.
	Get(key string) (int, bool)
	// Put sets key to v and marks it most recently used. If the cache is
	// full and key is new, the least recently used key is evicted first.
	Put(key string, v int)
	// Len is the number of keys held.
	Len() int
}

// Factory builds an empty cache holding at most capacity keys (>= 1).
type Factory func(capacity int) Cache

const (
	Cases = 16
	Ops   = 14
)

var keys = []string{"a", "b", "c", "d", "e", "f"}

// Spec describes this spec to Assertpay.
func Spec() check.Spec {
	return check.Spec{
		Name:  "lru",
		Doc:   "A fixed-capacity least-recently-used cache: Get refreshes a key, Put inserts or updates and evicts the least recently used key when full. Checked against a slice model.",
		Tests: Tests,
	}
}

type op struct {
	put bool
	key string
	v   int
}

// Tests builds the tests for impl (a Factory or a func(int) Cache).
func Tests(impl any, seed uint64) []check.Test {
	f, ok := asFactory(impl)
	if !ok {
		return []check.Test{{Name: "Type", Fn: func(t *check.T) { t.Fatal("implementation is not an lru.Factory") }}}
	}
	tests := []check.Test{
		{"PutGet", run(f, 2, []op{{true, "a", 1}, {false, "a", 0}})},
		{"Evict", run(f, 2, []op{{true, "a", 1}, {true, "b", 2}, {true, "c", 3}, {false, "a", 0}, {false, "c", 0}})},
		{"Update", run(f, 2, []op{{true, "a", 1}, {true, "a", 5}, {false, "a", 0}})},
		{"Missing", run(f, 1, []op{{false, "z", 0}})},
	}
	for i := 0; i < Cases; i++ {
		r := check.NewRand(check.Sub(seed, i))
		capacity := 1 + r.Intn(4)
		tests = append(tests, check.Test{Name: "Case" + check.Itoa(i), Fn: run(f, capacity, gen(r))})
	}
	return tests
}

func asFactory(impl any) (Factory, bool) {
	switch v := impl.(type) {
	case Factory:
		return v, v != nil
	case func(int) Cache:
		return Factory(v), v != nil
	}
	return nil, false
}

func gen(r *check.Rand) []op {
	ops := make([]op, Ops)
	for i := range ops {
		ops[i] = op{put: r.Intn(2) == 0, key: keys[r.Intn(len(keys))], v: r.Intn(100)}
	}
	return ops
}

func run(f Factory, capacity int, ops []op) func(t *check.T) {
	return func(t *check.T) {
		c := f(capacity)
		var order []string // least recent first
		vals := map[string]int{}
		trace := "cap " + check.Itoa(capacity) + ":"
		for _, o := range ops {
			if o.put {
				trace += " put(" + o.key + "," + check.Itoa(o.v) + ")"
				c.Put(o.key, o.v)
				if _, ok := vals[o.key]; ok {
					order = touch(order, o.key)
				} else {
					if len(order) == capacity {
						delete(vals, order[0])
						order = order[1:]
					}
					order = append(order, o.key)
				}
				vals[o.key] = o.v
			} else {
				trace += " get(" + o.key + ")"
				got, gotOK := c.Get(o.key)
				want, wantOK := vals[o.key]
				if wantOK {
					order = touch(order, o.key)
				}
				if got != want || gotOK != wantOK {
					t.Fatal(trace + " = " + pair(got, gotOK) + ", want " + pair(want, wantOK))
				}
			}
			if c.Len() != len(order) {
				t.Fatal(trace + ": Len() = " + check.Itoa(c.Len()) + ", want " + check.Itoa(len(order)))
			}
		}
	}
}

func touch(order []string, k string) []string {
	out := make([]string, 0, len(order))
	for _, x := range order {
		if x != k {
			out = append(out, x)
		}
	}
	return append(out, k)
}

func pair(v int, ok bool) string {
	if !ok {
		return "(missing)"
	}
	return check.Itoa(v)
}

// Package bad is a plausible but wrong lru implementation: Get does not
// refresh a key, so it evicts by insertion order (FIFO) instead of by use.
// The fixed examples miss it; generated cases catch it.
package bad

import "gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/aprh1/specs/lru/v1"

type cache struct {
	cap   int
	order []string
	vals  map[string]int
}

// New returns an empty cache.
func New(capacity int) lru.Cache { return &cache{cap: capacity, vals: map[string]int{}} }

func (c *cache) touch(k string) {
	out := c.order[:0:0]
	for _, x := range c.order {
		if x != k {
			out = append(out, x)
		}
	}
	c.order = append(out, k)
}

func (c *cache) Get(k string) (int, bool) {
	v, ok := c.vals[k]
	return v, ok
}

func (c *cache) Put(k string, v int) {
	if _, ok := c.vals[k]; !ok && len(c.order) == c.cap {
		delete(c.vals, c.order[0])
		c.order = c.order[1:]
	}
	c.vals[k] = v
	c.touch(k)
}

func (c *cache) Len() int { return len(c.order) }

