		t.Fatalf("CheckedAdd(MaxInt64-1,1) = %d %v", v, ok)
	}
	if v, ok := CheckedSub(-MaxInt64-1, 1); ok || v != 0 {
		t.Fatalf("CheckedSub(MinInt64,1) must overflow")
	}
	if v, ok := CheckedSub(10, 3); !ok || v != 7 {
