// ---------------------------------------------------------------------------
// Day-2 test: mixed-run invariant fuzz (design §7 T2 pattern).
// 3 seeds x 1000 pseudo-random moves (day 3: was 1 seed x 300 steps);
// the §4.2 invariant must hold after EVERY step, whether the
// attempted move succeeded or panicked.
// ---------------------------------------------------------------------------

func TestMixedRunInvariant(t *testing.T) {
	for _, seed := range []uint64{0x9E3779B97F4A7C15, 0x123456789ABCDEF0, 0xDEADBEEFCAFEBABE} {
		runMixedInvariant(t, seed, 1000)
	}
}

func runMixedInvariant(t *testing.T, seed uint64, steps int) {
	b := mustBounty(t)
	height := int64(1000)
	// Deterministic LCG (no math/rand dependency in Gno tests).
	var rng uint64 = seed
	next := func() uint64 {
		rng = rng*6364136223846793005 + 1442695040888963407
		return rng >> 33
	}
	findings := []Finding{}
	salts := []string{}
	titles := []string{}
	successes := 0
	for step := 0; step < steps; step++ {
		action := next() % 12
		var panicked bool
		switch action {
		case 0: // commit a new finding
			id := uint64(len(findings) + 1)
			var hunter address = hunterAddr
			if next()%2 == 0 {
				hunter = hunter2Addr
			}
			sev := Severity(1 + next()%4)
			salt := revealSalt
			if next()%2 == 0 {
				salt = revealSalt2
			}
			// One distinct title per finding index: the day-3 hash
			// rule blocks re-committing a hash carried by any
			// non-expired finding, and the fuzz only has two salts
			// — without a varying title it would run out of fresh
			// hashes after the first few findings.
			title := revealTitle
			if len(findings) > 0 {
				title = revealTitle + " #" + strconv.Itoa(len(findings))
			}
			hash := MakeCommitment(b.ID(), sev, title, revealPoc, salt)
			panicked = tryMove(func() {
				f := CommitFinding(&b, findings, id, hunter, sev, hash, height)
				findings = append(findings, f)
				salts = append(salts, salt)
				titles = append(titles, title)
			})
		case 1: // reveal a random finding
			if len(findings) == 0 {
				continue
			}
			i := int(next() % uint64(len(findings)))
			salt := salts[i]
			title := titles[i]
			panicked = tryMove(func() {
				findings[i].Reveal(&b, findings[i].Hunter(), title, revealPoc, salt, height)
			})
		case 2: // arbiter accept, random final tier
			if len(findings) == 0 {
				continue
			}
			i := int(next() % uint64(len(findings)))
			finalSev := Severity(1 + next()%4)
			others := othersExcluding(findings, i)
			panicked = tryMove(func() {
				findings[i].ApplyVerdict(&b, arbiterAddr, VerdictAccept, finalSev, "fuzz verdict", 0, nil, others, height)
			})
		case 3: // arbiter reject
			if len(findings) == 0 {
				continue
			}
			i := int(next() % uint64(len(findings)))
			panicked = tryMove(func() {
				findings[i].ApplyVerdict(&b, arbiterAddr, VerdictReject, 0, "fuzz reject", 0, nil, nil, height)
			})
		case 4: // arbiter duplicate against another finding
			if len(findings) < 2 {
				continue
			}
			i := int(next() % uint64(len(findings)))
			j := int(next() % uint64(len(findings)))
			if i == j {
				continue
			}
			orig := &findings[j]
			panicked = tryMove(func() {
				findings[i].ApplyVerdict(&b, arbiterAddr, VerdictDuplicate, 0, "fuzz duplicate", orig.ID(), orig, nil, height)
			})
		case 5: // dispute
			if len(findings) == 0 {
				continue
			}
			i := int(next() % uint64(len(findings)))
			panicked = tryMove(func() {
				findings[i].Dispute(findings[i].Hunter(), "fuzz dispute", height)
			})
		case 6: // claim payout
			if len(findings) == 0 {
				continue
			}
			i := int(next() % uint64(len(findings)))
			others := othersExcluding(findings, i)
			panicked = tryMove(func() {
				findings[i].ClaimPayout(&b, findings[i].Hunter(), others, height)
			})
		case 7: // top up the pool
			amount := int64(100000 + next()%900000)
			panicked = tryMove(func() { b.TopUp(amount) })
		case 8: // expire a commit
			if len(findings) == 0 {
				continue
			}
			i := int(next() % uint64(len(findings)))
			panicked = tryMove(func() { findings[i].ExpireCommit(height) })
		case 9: // advance the chain
			height += int64(1 + next()%5000)
			panicked = false
		case 10: // sponsor verdict (accept or reject)
			if len(findings) == 0 {
				continue
			}
			i := int(next() % uint64(len(findings)))
			if next()%2 == 0 {
				finalSev := Severity(1 + next()%4)
				others := othersExcluding(findings, i)
				panicked = tryMove(func() {
					findings[i].SponsorVerdict(&b, sponsorAddr, VerdictAccept, finalSev, "fuzz sponsor accept", 0, nil, others, height)
				})
			} else {
				panicked = tryMove(func() {
					findings[i].SponsorVerdict(&b, sponsorAddr, VerdictReject, 0, "fuzz sponsor reject", 0, nil, nil, height)
				})
			}
		case 11: // mark fixed + auto-disclose sweep
			ptrs := []*Finding{}
			for i := range findings {
				ptrs = append(ptrs, &findings[i])
			}
			panicked = tryMove(func() { MarkFixedBounty(&b, sponsorAddr, height, ptrs) })
			for i := range findings {
				tryMove(func() { findings[i].AutoDisclose(height) })
			}
		}
		if !panicked {
			successes++
		}
		// The invariant must hold after every step, success or panic.
		assertInvariants(t, &b, findings)
	}
	if len(findings) < 10 {
		t.Fatalf("fuzz seed %x committed only %d findings in %d steps", seed, len(findings), steps)
	}
	if successes < 100 {
		t.Fatalf("fuzz seed %x succeeded only %d/%d moves — the run is not exercising the machine", seed, successes, steps)
	}
	// Money accounting must close exactly (also covered by CheckInvariant).
	if b.PoolLeft()+b.PaidOut()+b.Refunded() != b.PoolTotal() {
		t.Fatalf("fuzz seed %x pool accounting broken: left %d paid %d refunded %d total %d",
			seed, b.PoolLeft(), b.PaidOut(), b.Refunded(), b.PoolTotal())
	}
	t.Logf("fuzz seed %x: %d steps, %d findings, %d successful moves, pool left %d paid %d",
		seed, steps, len(findings), successes, b.PoolLeft(), b.PaidOut())
}

// Package tavernrules — state-machine moves (design §5, §6).
//
// This file holds every transition of the BugTavern protocol as pure
// logic: no coins, no chain, no storage. Each move receives the acting
// address and the current block height as plain arguments; the realm
// (day 5) supplies them from cur.Previous().Address() and
// runtime.ChainHeight(), and executes the returned Payout with
// SendCoins. Rules never touch a banker.
//
// Move discipline (design §7 T2/T10/T11):
//   - validate state and actor FIRST (wrong state / wrong actor panics),
//   - then mutate (CEI: state moves to final BEFORE any payout is built),
//   - then CheckInvariant (§4.2) — a violated invariant panics instead of
//     ever returning a corrupt state.
//
// All validation panics: in Gno a panic aborts the transaction, so a
// failed move can never leave a half-mutated bounty or finding behind.
//
// Windows (design §6.3) are block heights, computed by the helpers at
// the top of this file. All deadline additions are checked math: a
// height near MaxInt64 panics instead of wrapping.
package tavernrules

// ---------------------------------------------------------------------------
// Deadline helpers (design §6.3). Each returns the last height at which
// the action is still allowed, or the first height at which the next
// actor may act — see the comment on each function.
// ---------------------------------------------------------------------------

// addWindow returns height + window, panicking on int64 overflow
// instead of wrapping silently (design §7 T11).
func addWindow(height, window int64) int64 {
	v, ok := CheckedAdd(height, window)
	if !ok {
		panic("deadline height overflow")
	}
	return v
}

// RevealDeadlineAt is the last height at which a commit may be revealed.
func RevealDeadlineAt(committedAt int64) int64 {
	return addWindow(committedAt, RevealWindow)
}

// ReviewDeadlineAt is the last height at which the arbiter may give a
// verdict on a revealed finding.
func ReviewDeadlineAt(revealedAt int64) int64 {
	return addWindow(revealedAt, ReviewWindow)
}

// SponsorDeadlineAt is the last height at which the sponsor may give a
// verdict after the arbiter's review window has expired.
func SponsorDeadlineAt(reviewDeadline int64) int64 {
	return addWindow(reviewDeadline, SponsorWindow)
}

// ClaimableAfter is the height after which the hunter may claim the
// payout: height must be strictly greater than this value (arbiter
// window + sponsor window both fully elapsed).
func ClaimableAfter(reviewDeadline int64) int64 {
	return addWindow(reviewDeadline, SponsorWindow)
}

// DisputeDeadlineAt is the last height at which the hunter may dispute
// a rejection.
func DisputeDeadlineAt(verdictAt int64) int64 {
	return addWindow(verdictAt, DisputeWindow)
}

// DisclosureDeadlineAt is the height after which an Accepted finding
// becomes Disclosed automatically even without MarkFixed.
func DisclosureDeadlineAt(verdictAt int64) int64 {
	return addWindow(verdictAt, FixWindow)
}

// DisputeReviewDeadlineAt is the last height at which the arbiter may
// re-decide a Disputed finding (design §6.3 ladder applied to
// disputes: the arbiter gets ReviewWindow from the dispute height).
func DisputeReviewDeadlineAt(disputedAt int64) int64 {
	return addWindow(disputedAt, ReviewWindow)
}

// DisputeClaimableAfter is the height after which the hunter may claim
// a Disputed finding: height must be strictly greater than this value
// (arbiter dispute-review window + sponsor window both fully elapsed).
func DisputeClaimableAfter(disputedAt int64) int64 {
	return addWindow(DisputeReviewDeadlineAt(disputedAt), SponsorWindow)
}

// ---------------------------------------------------------------------------
// Helpers shared by the moves.
// ---------------------------------------------------------------------------

// IsInFlight reports whether a finding blocks Cancel/Close: a finding
// is in flight while it is Committed, Revealed, or Disputed. A Rejected
// finding is NOT in flight by status, but it still blocks Cancel/Close
// while it is disputable — see AnyDisputable. Expired, Accepted,
// Duplicate, Rejected-past-window and Disclosed findings never block.
func IsInFlight(s FindingStatus) bool {
	switch s {
	case FindingCommitted, FindingRevealed, FindingDisputed:
		return true
	default:
		return false
	}
}

// AnyDisputable reports whether any finding in the slice is a Rejected
// finding whose dispute window is still open at height (not yet
// disputed, height not past verdictAt + DisputeWindow). Such a finding
// blocks Cancel/Close: cancelling first would strand the hunter's
// one dispute, since a re-verdict needs an Open bounty.
func AnyDisputable(findings []Finding, height int64) bool {
	for _, f := range findings {
		if f.Status() != FindingRejected || f.DisputedBefore() {
			continue
		}
		if height <= DisputeDeadlineAt(f.VerdictAt()) {
			return true
		}
	}
	return false
}

// AnyInFlight reports whether any finding in the slice is in flight.
func AnyInFlight(findings []Finding) bool {
	for _, f := range findings {
		if IsInFlight(f.Status()) {
			return true
		}
	}
	return false
}

// TierAlreadyPaid reports whether a severity tier has already been paid
// for this bounty (design §5.6: each tier pays at most once, first
// valid finding per tier). Callers pass the OTHER findings of the
// bounty — the finding being decided must not be in the slice.
func TierAlreadyPaid(findings []Finding, bountyID uint64, sev Severity) bool {
	for _, f := range findings {
		if f.BountyID() != bountyID {
			continue
		}
		if f.SeverityFinal() != sev {
			continue
		}
		if f.Status() == FindingAccepted || f.Status() == FindingDisclosed {
			return true
		}
	}
	return false
}

// checkBountyInvariant panics when a bounty violates §4.2.
func checkBountyInvariant(b *Bounty) {
	if msg := b.CheckInvariant(); msg != "" {
		panic("bounty invariant violated: " + msg)
	}
}

// checkFindingInvariant panics when a finding violates §4.2.
func checkFindingInvariant(f *Finding) {
	if msg := f.CheckInvariant(); msg != "" {
		panic("finding invariant violated: " + msg)
	}
}

// checkBoth panics when either side of a move violates §4.2.
func checkBoth(b *Bounty, f *Finding) {
	checkBountyInvariant(b)
	checkFindingInvariant(f)
}

// ---------------------------------------------------------------------------
// Verdict — the arbiter/sponsor decision on a revealed finding.
// ---------------------------------------------------------------------------

// Verdict is the decision an arbiter (or the sponsor, as backup) gives.
type Verdict uint8

const (
	VerdictAccept Verdict = iota + 1
	VerdictDuplicate
	VerdictReject
)

// Valid reports whether v is one of the three verdicts.
func (v Verdict) Valid() bool {
	return v >= VerdictAccept && v <= VerdictReject
}

// String returns the verdict name.
func (v Verdict) String() string {
	switch v {
	case VerdictAccept:
		return "Accept"
	case VerdictDuplicate:
		return "Duplicate"
	case VerdictReject:
		return "Reject"
	default:
		return "Unknown"
	}
}

// ---------------------------------------------------------------------------
// Bounty moves.
// ---------------------------------------------------------------------------

// TopUp adds amount to the bounty pool (poolTotal and poolLeft grow by
// the same amount). Only an Open bounty can be topped up. The realm
// must have already received exactly `amount` ugnot with the call.
func (b *Bounty) TopUp(amount int64) {
	if b.status != BountyOpen {
		panic("top-up only on an Open bounty")
	}
	if amount <= 0 {
		panic("top-up amount must be positive")
	}
	total, ok := CheckedAdd(b.poolTotal, amount)
	if !ok {
		panic("top-up overflows pool total")
	}
	left, ok := CheckedAdd(b.poolLeft, amount)
	if !ok {
		panic("top-up overflows pool left")
	}
	b.poolTotal = total
	b.poolLeft = left
	checkBountyInvariant(b)
}

// CancelBounty cancels an Open bounty and refunds the remaining pool to
// the sponsor. Only the sponsor may cancel, and only while no finding
// is in flight and no Rejected finding is still disputable at height.
// It returns the refund payout the realm must execute
// (zero Payout when nothing is left to refund).
func CancelBounty(b *Bounty, actor address, height int64, findings []Finding) Payout {
	if actor != b.sponsor {
		panic("only the sponsor can cancel a bounty")
	}
	if b.status != BountyOpen {
		panic("only an Open bounty can be cancelled")
	}
	if AnyInFlight(findings) {
		panic("cannot cancel with findings in flight")
	}
	if AnyDisputable(findings, height) {
		panic("cannot cancel while a rejected finding can still be disputed")
	}
	var p Payout
	if b.poolLeft > 0 {
		p = b.RecordRefund(b.sponsor, b.poolLeft)
	}
	b.Cancel()
	checkBountyInvariant(b)
	return p
}

// CloseBounty closes an Open bounty after its deadline and refunds the
// remaining pool to the sponsor. Only the sponsor may close, only when
// height is strictly past the deadline, and only while no finding is
// in flight and no Rejected finding is still disputable at height.
// It returns the refund payout the realm must execute
// (zero Payout when nothing is left to refund).
func CloseBounty(b *Bounty, actor address, height int64, findings []Finding) Payout {
	if actor != b.sponsor {
		panic("only the sponsor can close a bounty")
	}
	if b.status != BountyOpen {
		panic("only an Open bounty can be closed")
	}
	if height <= b.deadline {
		panic("cannot close before the bounty deadline")
	}
	if AnyInFlight(findings) {
		panic("cannot close with findings in flight")
	}
	if AnyDisputable(findings, height) {
		panic("cannot close while a rejected finding can still be disputed")
	}
	var p Payout
	if b.poolLeft > 0 {
		p = b.RecordRefund(b.sponsor, b.poolLeft)
	}
	b.Close()
	checkBountyInvariant(b)
	return p
}

// MarkFixedBounty marks the audited realm fixed: every Accepted finding
// of this bounty becomes Disclosed and appears on the public
// disclosure page. Only the sponsor, only while the bounty is Open.
// It returns how many findings were disclosed.
func MarkFixedBounty(b *Bounty, actor address, height int64, findings []*Finding) int {
	if actor != b.sponsor {
		panic("only the sponsor can mark a bounty fixed")
	}
	if b.status != BountyOpen {
		panic("only an Open bounty can be marked fixed")
	}
	n := 0
	for _, f := range findings {
		if f == nil {
			panic("nil finding in list")
		}
		if f.BountyID() != b.id {
			panic("finding belongs to another bounty")
		}
		if f.Status() == FindingAccepted {
			f.MarkDisclosed(height)
			n++
		}
	}
	checkBountyInvariant(b)
	return n
}

// ---------------------------------------------------------------------------
// Finding moves.
// ---------------------------------------------------------------------------

// CommitFinding records a hunter's hash commitment against an Open
// bounty. It panics unless the bounty is Open, height is not past the
// bounty deadline, the hash is a valid 64-hex digest, and no OTHER
// finding on the same bounty already carries this exact hash —
// EXCEPT an Expired one (design §7 T3: copying another hunter's
// visible commit hash must not squat the finding — the copycat cannot
// reveal without the salt, and the hash check rejects the squat
// outright). The block covers decided findings too: once a finding
// is Revealed its salt is public, so a copycat could otherwise
// re-commit the identical hash and, if the arbiter corrected the
// tier, be paid for the same bug a second time at another tier.
// An Expired finding does not block a fresh commit of the same hash:
// the hunter re-commits with a new salt. The reveal deadline is
// height + RevealWindow.
func CommitFinding(b *Bounty, others []Finding, id uint64, hunter address, severity Severity, commitHash string, height int64) Finding {
	if b.status != BountyOpen {
		panic("cannot commit to a bounty that is not Open")
	}
	if height > b.deadline {
		panic("cannot commit after the bounty deadline")
	}
	for _, o := range others {
		if o.BountyID() != b.id || o.CommitHash() != commitHash {
			continue
		}
		if o.Status() != FindingExpired {
			panic("commit hash already in use by another finding on this bounty")
		}
	}
	f := NewFinding(id, b.id, hunter, severity, commitHash, height, RevealDeadlineAt(height))
	checkFindingInvariant(&f)
	return f
}

// Reveal discloses a committed finding: the hunter supplies the title,
// PoC URL and salt, the commitment is recomputed with MakeCommitment
// and must match the stored hash exactly, or the call panics. Only
// the committing hunter, only while Committed, only up to the reveal
// deadline, and only on an Open bounty. On success the finding is
// Revealed and the review deadline is height + ReviewWindow.
func (f *Finding) Reveal(b *Bounty, actor address, title, pocURL, salt string, height int64) {
	if b.id != f.bountyID {
		panic("finding does not belong to this bounty")
	}
	if b.status != BountyOpen {
		panic("cannot reveal on a bounty that is not Open")
	}
	if actor != f.hunter {
		panic("only the hunter who committed can reveal")
	}
	if f.status != FindingCommitted {
		panic("only a Committed finding can be revealed")
	}
	if height > f.revealDeadline {
		panic("reveal deadline has passed")
	}
	if msg := ValidateReveal(title, pocURL, salt); msg != "" {
		panic(msg)
	}
	if MakeCommitment(f.bountyID, f.severity, title, pocURL, salt) != f.commitHash {
		panic("commitment mismatch: revealed contents do not match the commit hash")
	}
	f.title = title
	f.pocURL = pocURL
	f.revealedAt = height
	f.reviewDeadline = ReviewDeadlineAt(height)
	f.status = FindingRevealed
	checkFindingInvariant(f)
}

// ExpireCommit lapses a commit that was never revealed: only a
// Committed finding, only once height is strictly past its reveal
// deadline. The finding becomes Expired (final) and can never be
// revealed; it no longer blocks Cancel/Close. Expiry is also enforced
// implicitly — Reveal panics past the deadline — this move just makes
// the lapse explicit and final.
func (f *Finding) ExpireCommit(height int64) {
	if f.status != FindingCommitted {
		panic("only a Committed finding can expire")
	}
	if height <= f.revealDeadline {
		panic("reveal deadline has not passed yet")
	}
	f.status = FindingExpired
	checkFindingInvariant(f)
}

// ApplyVerdict is the arbiter's verdict on a Revealed finding, or the
// re-verdict on a Disputed finding. From Revealed the arbiter must
// decide by the review deadline — after that the right passes to the
// sponsor (see SponsorVerdict) and the arbiter panics. From Disputed
// the arbiter must re-decide by disputedAt + ReviewWindow — after
// that the right passes to the sponsor the same way. Accept pays the
// final tier price from the pool (CEI: the finding moves to Accepted
// first); Duplicate and Reject pay nothing.
func (f *Finding) ApplyVerdict(b *Bounty, by address, v Verdict, finalSeverity Severity, reason string, duplicateOf uint64, original *Finding, others []Finding, height int64) Payout {
	return f.doVerdict(b, by, v, finalSeverity, reason, duplicateOf, original, others, height, true)
}

// SponsorVerdict is the sponsor's backup verdict: only the sponsor,
// only on a Revealed finding (after the arbiter's review window and
// up to reviewDeadline + SponsorWindow), or on a Disputed finding
// (after the arbiter's dispute-review window and up to
// disputedAt + ReviewWindow + SponsorWindow). After those windows
// the hunter may claim the payout directly (see ClaimPayout).
func (f *Finding) SponsorVerdict(b *Bounty, by address, v Verdict, finalSeverity Severity, reason string, duplicateOf uint64, original *Finding, others []Finding, height int64) Payout {
	return f.doVerdict(b, by, v, finalSeverity, reason, duplicateOf, original, others, height, false)
}

// doVerdict is the shared verdict core. arbiter=true enforces the
// arbiter's actor + review window; arbiter=false enforces the
// sponsor's actor + sponsor window.
func (f *Finding) doVerdict(b *Bounty, by address, v Verdict, finalSeverity Severity, reason string, duplicateOf uint64, original *Finding, others []Finding, height int64, arbiter bool) Payout {
	if b.id != f.bountyID {
		panic("finding does not belong to this bounty")
	}
	if b.status != BountyOpen {
		panic("cannot give a verdict on a bounty that is not Open")
	}
	if !v.Valid() {
		panic("invalid verdict")
	}
	if len(reason) > MaxReasonLen {
		panic("verdict reason must be at most 300 characters")
	}
	if arbiter {
		if by != b.arbiter {
			panic("only the bounty arbiter can give a verdict")
		}
		if f.status == FindingRevealed {
			if height > f.reviewDeadline {
				panic("arbiter review window has expired; the sponsor decides now")
			}
		} else if f.status == FindingDisputed {
			if height > DisputeReviewDeadlineAt(f.disputedAt) {
				panic("arbiter dispute-review window has expired; the sponsor decides now")
			}
		} else {
			panic("verdict requires a Revealed or Disputed finding")
		}
	} else {
		if by != b.sponsor {
			panic("only the sponsor can give a sponsor verdict")
		}
		if f.status == FindingRevealed {
			if height <= f.reviewDeadline {
				panic("sponsor verdict only after the arbiter review window")
			}
			if height > SponsorDeadlineAt(f.reviewDeadline) {
				panic("sponsor verdict window has expired; the hunter may claim")
			}
		} else if f.status == FindingDisputed {
			if height <= DisputeReviewDeadlineAt(f.disputedAt) {
				panic("sponsor verdict only after the arbiter dispute-review window")
			}
			if height > DisputeClaimableAfter(f.disputedAt) {
				panic("sponsor verdict window has expired; the hunter may claim")
			}
		} else {
			panic("sponsor verdict requires a Revealed or Disputed finding")
		}
	}
	switch v {
	case VerdictAccept:
		return f.doAccept(b, by, finalSeverity, reason, others, height)
	case VerdictDuplicate:
		f.doDuplicate(b, by, reason, duplicateOf, original, height)
		return Payout{}
	case VerdictReject:
		f.doReject(b, by, reason, height)
		return Payout{}
	default:
		panic("invalid verdict")
	}
}

// doAccept pays the final tier price to the hunter. The arbiter may
// correct the hunter's claimed severity up or down; the price follows
// the FINAL tier. It panics when the decider is the hunter
// themselves (an arbiter or sponsor must never pay themselves from
// the sponsor's pool), when the tier was already paid for this
// bounty (§5.6), or the pool cannot cover the tier price.
func (f *Finding) doAccept(b *Bounty, by address, finalSeverity Severity, reason string, others []Finding, height int64) Payout {
	if by == f.hunter {
		panic("the decider cannot accept their own finding")
	}
	if !finalSeverity.Valid() {
		panic("final severity must be a valid tier")
	}
	if b.TierPaid(finalSeverity) {
		panic("this severity tier has already been paid for this bounty")
	}
	if TierAlreadyPaid(others, f.bountyID, finalSeverity) {
		panic("this severity tier has already been paid for this bounty")
	}
	price := b.PriceFor(finalSeverity)
	if price <= 0 {
		panic("final severity has no configured price")
	}
	if price > b.poolLeft {
		panic("pool left is below the tier price")
	}
	// CEI: finding to its final state first, then the bounty payout.
	f.severityFinal = finalSeverity
	f.verdictBy = by
	f.verdictAt = height
	f.verdictReason = reason
	f.paidAmount = price
	f.status = FindingAccepted
	p := b.RecordPayout(f.hunter, finalSeverity, price)
	checkBoth(b, f)
	return p
}

// doDuplicate marks the finding a duplicate of an earlier finding. The
// original must be a different finding on the same bounty, committed
// strictly earlier — or in the same block with a lower id (finding
// ids are assigned in commit order, so a lower id is the earlier
// commit inside one block) — and currently Revealed, Accepted or
// Disclosed. No money moves.
func (f *Finding) doDuplicate(b *Bounty, by address, reason string, duplicateOf uint64, original *Finding, height int64) {
	if duplicateOf == 0 {
		panic("duplicate verdict requires the original finding id")
	}
	if original == nil {
		panic("duplicate verdict requires the original finding")
	}
	if original.ID() != duplicateOf {
		panic("duplicateOf does not match the original finding")
	}
	if original.BountyID() != f.bountyID {
		panic("original finding belongs to another bounty")
	}
	if original.ID() == f.id {
		panic("a finding cannot duplicate itself")
	}
	if original.CommittedAt() > f.committedAt {
		panic("original finding must have been committed earlier")
	}
	if original.CommittedAt() == f.committedAt && original.ID() > f.id {
		panic("original finding must have the lower id when committed in the same block")
	}
	switch original.Status() {
	case FindingRevealed, FindingAccepted, FindingDisclosed:
	default:
		panic("original finding must be Revealed, Accepted or Disclosed")
	}
	f.verdictBy = by
	f.verdictAt = height
	f.verdictReason = reason
	f.duplicateOf = duplicateOf
	f.status = FindingDuplicate
	b.RecordDuplicate()
	checkBoth(b, f)
}

// doReject rejects the finding. A reason is mandatory (<= 300 chars)
// and stays public. The hunter may dispute once, inside the dispute
// window (see Dispute).
func (f *Finding) doReject(b *Bounty, by address, reason string, height int64) {
	if len(reason) == 0 {
		panic("reject verdict requires a reason")
	}
	f.verdictBy = by
	f.verdictAt = height
	f.verdictReason = reason
	f.status = FindingRejected
	b.RecordRejected()
	checkBoth(b, f)
}

// Dispute protests a rejection. Only the hunter, only once per finding,
// only inside DisputeWindow blocks after the verdict. The finding
// becomes Disputed and awaits a re-verdict from the arbiter.
func (f *Finding) Dispute(actor address, reason string, height int64) {
	if actor != f.hunter {
		panic("only the hunter can dispute")
	}
	if f.status != FindingRejected {
		panic("only a Rejected finding can be disputed")
	}
	if f.disputed {
		panic("a finding can be disputed only once")
	}
	if height < f.verdictAt {
		panic("dispute height is before the verdict")
	}
	if height > DisputeDeadlineAt(f.verdictAt) {
		panic("dispute window has expired")
	}
	if len(reason) == 0 || len(reason) > MaxReasonLen {
		panic("dispute reason must be 1-300 characters")
	}
	f.disputed = true
	f.disputeReason = reason
	f.disputedAt = height
	f.status = FindingDisputed
	checkFindingInvariant(f)
}

// ClaimPayout is the hunter's last-resort claim: only the hunter, only
// on a Revealed finding (once height is strictly past
// reviewDeadline + SponsorWindow — arbiter silent, then sponsor
// silent) or on a Disputed finding (once height is strictly past
// disputedAt + ReviewWindow + SponsorWindow — arbiter silent on the
// re-verdict, then sponsor silent). It pays the CLAIMED tier price
// from the pool — the hunter's own severity claim, since nobody
// corrected it — and moves the finding to Accepted. It panics when
// the tier was already paid or the pool cannot cover the tier price.
func (f *Finding) ClaimPayout(b *Bounty, actor address, others []Finding, height int64) Payout {
	if b.id != f.bountyID {
		panic("finding does not belong to this bounty")
	}
	if b.status != BountyOpen {
		panic("cannot claim a payout on a bounty that is not Open")
	}
	if actor != f.hunter {
		panic("only the hunter can claim the payout")
	}
	if f.status != FindingRevealed && f.status != FindingDisputed {
		panic("only a Revealed or Disputed finding can be claimed")
	}
	if f.status == FindingRevealed {
		if height <= ClaimableAfter(f.reviewDeadline) {
			panic("claim window has not opened: arbiter and sponsor may still decide")
		}
	} else {
		if height <= DisputeClaimableAfter(f.disputedAt) {
			panic("claim window has not opened: arbiter and sponsor may still decide the dispute")
		}
	}
	if b.TierPaid(f.severity) {
		panic("this severity tier has already been paid for this bounty")
	}
	if TierAlreadyPaid(others, f.bountyID, f.severity) {
		panic("this severity tier has already been paid for this bounty")
	}
	price := b.PriceFor(f.severity)
	if price <= 0 {
		panic("claimed severity has no configured price")
	}
	if price > b.poolLeft {
		panic("pool left is below the tier price")
	}
	// CEI: finding to its final state first, then the bounty payout.
	f.severityFinal = f.severity
	f.verdictBy = actor
	f.verdictAt = height
	f.verdictReason = "timeout: arbiter and sponsor silent"
	f.paidAmount = price
	f.status = FindingAccepted
	p := b.RecordPayout(f.hunter, f.severity, price)
	checkBoth(b, f)
	return p
}

// MarkDisclosed moves an Accepted finding to Disclosed (public
// disclosure page). Called by MarkFixedBounty, or by the realm for a
// single finding.
func (f *Finding) MarkDisclosed(height int64) {
	if f.status != FindingAccepted {
		panic("only an Accepted finding can be disclosed")
	}
	f.status = FindingDisclosed
	f.disclosedAt = height
	checkFindingInvariant(f)
}

// AutoDisclose moves an Accepted finding to Disclosed once the fix
// window has elapsed (height strictly past verdictAt + FixWindow),
// even when the sponsor never called MarkFixed.
func (f *Finding) AutoDisclose(height int64) {
	if f.status != FindingAccepted {
		panic("only an Accepted finding can be auto-disclosed")
	}
	if height <= DisclosureDeadlineAt(f.verdictAt) {
		panic("fix window has not expired")
	}
	f.status = FindingDisclosed
	f.disclosedAt = height
	checkFindingInvariant(f)
}

// Package tavernrules holds the pure rules of BugTavern.
//
// Pure means: no coins, no chain, no storage. Every function here takes
// its inputs as plain arguments (actor addresses, block heights) so it
// can be unit-tested with `gno test` and no node.
//
// Design reference: BugTavern-DESIGN.md §4. All struct fields are
// private; only the move methods in this package may change them.
// Readers return value copies, never pointers into stored state.
//
// Money invariants (design §4.2), checked by Bounty.CheckInvariant:
//   - poolLeft + paidOut + refunded == poolTotal
//   - poolLeft >= 0, and a payout only happens when poolLeft >= amount
//   - no Open bounty with deadline < createdAt
//   - no finding with revealDeadline <= committedAt
package tavernrules

import (
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"
)

// ---------------------------------------------------------------------------
// Limits (design §3.4) and windows (design §6.3).
// Lengths are byte lengths: storage deposit is charged per byte.
// ---------------------------------------------------------------------------

const (
	// MaxTitleLen is the longest bounty/finding title.
	MaxTitleLen = 100
	// MaxScopeLen is the longest bounty scope/description.
	MaxScopeLen = 1000
	// MaxPocURLLen is the longest PoC URL.
	MaxPocURLLen = 300
	// MaxReasonLen is the longest reject/dispute reason.
	MaxReasonLen = 300
	// MinBountyReward is the smallest poolTotal of a bounty (1 GNOT).
	MinBountyReward int64 = 1000000
	// MinTierPrice is the smallest price of one severity tier (0.1 GNOT).
	MinTierPrice int64 = 100000
	// MinSaltLen is the shortest reveal salt (entropy cannot be checked
	// on-chain, only length — see MakeCommitment).
	MinSaltLen = 16
	// CommitHashLen is the length of a lowercase hex sha256 digest.
	CommitHashLen = 64
)

const (
	// RevealWindow blocks (~24h at ~3.5s/block) to reveal after commit.
	RevealWindow int64 = 24600
	// ReviewWindow blocks (~3 days) for the arbiter to give a verdict.
	ReviewWindow int64 = 72000
	// SponsorWindow blocks (~3 days) for the sponsor verdict after the
	// arbiter's window expires.
	SponsorWindow int64 = 72000
	// DisputeWindow blocks (~36h) for the hunter to dispute a rejection.
	DisputeWindow int64 = 36000
	// FixWindow blocks (~14 days) after which an Accepted finding
	// becomes Disclosed even without MarkFixed.
	FixWindow int64 = 345600
)

// MaxInt64 is the largest int64 value, for checked math.
const MaxInt64 int64 = 9223372036854775807

// ---------------------------------------------------------------------------
// Checked math (design §7 T11). Gno integers wrap silently, so every
// addition that touches money must go through these helpers.
// ---------------------------------------------------------------------------

// CheckedAdd returns a+b and true, or 0 and false on overflow.
func CheckedAdd(a, b int64) (int64, bool) {
	if b > 0 && a > MaxInt64-b {
		return 0, false
	}
	if b < 0 && a < -MaxInt64-1-b {
		return 0, false
	}
	return a + b, true
}

// CheckedSub returns a-b and true, or 0 and false on overflow.
func CheckedSub(a, b int64) (int64, bool) {
	if b < 0 && a > MaxInt64+b {
		return 0, false
	}
	if b > 0 && a < -MaxInt64-1+b {
		return 0, false
	}
	return a - b, true
}

// ---------------------------------------------------------------------------
// Severity
// ---------------------------------------------------------------------------

// Severity is the reward tier of a finding.
type Severity uint8

const (
	SevLow Severity = iota + 1
	SevMedium
	SevHigh
	SevCritical
)

// Valid reports whether s is one of the four tiers.
func (s Severity) Valid() bool {
	return s >= SevLow && s <= SevCritical
}

// String returns the tier name (for Render and events).
func (s Severity) String() string {
	switch s {
	case SevLow:
		return "Low"
	case SevMedium:
		return "Medium"
	case SevHigh:
		return "High"
	case SevCritical:
		return "Critical"
	default:
		return "Unknown"
	}
}

// ---------------------------------------------------------------------------
// BountyStatus
// ---------------------------------------------------------------------------

// BountyStatus is the lifecycle state of a bounty.
type BountyStatus uint8

const (
	BountyOpen BountyStatus = iota + 1
	// BountyClosed is final: pool spent, or deadline passed and the
	// remainder refunded.
	BountyClosed
	// BountyCancelled is final: sponsor cancelled while no finding was
	// in flight, remainder refunded.
	BountyCancelled
)

// Valid reports whether s is a known bounty status.
func (s BountyStatus) Valid() bool {
	return s >= BountyOpen && s <= BountyCancelled
}

// String returns the status name.
func (s BountyStatus) String() string {
	switch s {
	case BountyOpen:
		return "Open"
	case BountyClosed:
		return "Closed"
	case BountyCancelled:
		return "Cancelled"
	default:
		return "Unknown"
	}
}

// ---------------------------------------------------------------------------
// FindingStatus
// ---------------------------------------------------------------------------

// FindingStatus is the lifecycle state of a finding.
type FindingStatus uint8

const (
	FindingCommitted FindingStatus = iota + 1 // hash only, not revealed
	FindingRevealed                           // revealed, awaiting verdict
	FindingAccepted                           // final: paid
	FindingDuplicate                          // final: duplicate, not paid
	FindingRejected                           // final unless disputed
	FindingDisputed                           // rejection disputed, awaiting re-verdict
	FindingDisclosed                          // final: accepted and publicly disclosed
	FindingExpired                            // final: commit lapsed past revealDeadline, never revealed
)

// Valid reports whether s is a known finding status.
func (s FindingStatus) Valid() bool {
	return s >= FindingCommitted && s <= FindingExpired
}

// IsFinal reports whether no further move is allowed from this status.
func (s FindingStatus) IsFinal() bool {
	switch s {
	case FindingAccepted, FindingDuplicate, FindingDisclosed, FindingExpired:
		return true
	case FindingRejected:
		// Rejected is final only once the dispute window has passed;
		// that is a height check, not a status property.
		return false
	default:
		return false
	}
}

// String returns the status name.
func (s FindingStatus) String() string {
	switch s {
	case FindingCommitted:
		return "Committed"
	case FindingRevealed:
		return "Revealed"
	case FindingAccepted:
		return "Accepted"
	case FindingDuplicate:
		return "Duplicate"
	case FindingRejected:
		return "Rejected"
	case FindingDisputed:
		return "Disputed"
	case FindingDisclosed:
		return "Disclosed"
	case FindingExpired:
		return "Expired"
	default:
		return "Unknown"
	}
}

// ---------------------------------------------------------------------------
// Commit-reveal (design §4.1).
// GATE DAY 1 — VERIFIED: crypto/sha256 exposes ONLY Sum256 in gno
// v1.8.0 (sha256.New does NOT exist — see gate report in README).
// Sum256 + encoding/hex is sufficient: the commitment is a one-shot
// hash, no streaming hash.Hash is needed. Full commit-reveal stands.
// ---------------------------------------------------------------------------

// MakeCommitment returns sha256_hex(bountyID|severity|title|pocURL|salt)
// with decimal integers and "|" separators, in fixed field order.
// The realm recomputes this at reveal and compares it to the stored
// commitHash; a mismatch panics.
func MakeCommitment(bountyID uint64, severity Severity, title, pocURL, salt string) string {
	preimage := strconv.FormatUint(bountyID, 10) + "|" +
		strconv.Itoa(int(severity)) + "|" +
		title + "|" + pocURL + "|" + salt
	sum := sha256.Sum256([]byte(preimage))
	return hex.EncodeToString(sum[:])
}

// ValidateCommitHash returns "" when h is a 64-char lowercase hex digest.
func ValidateCommitHash(h string) string {
	if len(h) != CommitHashLen {
		return "commit hash must be 64 hex chars"
	}
	for i := 0; i < len(h); i++ {
		c := h[i]
		if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
			return "commit hash must be lowercase hex"
		}
	}
	return ""
}

// ValidateSalt returns "" when the salt is long enough. Entropy cannot
// be checked on-chain; only length is enforced.
func ValidateSalt(salt string) string {
	if len(salt) < MinSaltLen {
		return "salt must be at least 16 characters"
	}
	return ""
}

// ---------------------------------------------------------------------------
// Bounty
// ---------------------------------------------------------------------------

// Bounty is one sponsored audit with a locked pool.
// v1 pricing model (design §5.6): poolTotal is the sum of the four tier
// prices, and each tier pays at most once (first valid finding per tier).
type Bounty struct {
	id        uint64
	sponsor   address
	arbiter   address // appointed by the sponsor; may be a third party
	title     string  // <= MaxTitleLen
	scope     string  // audited realm, <= MaxScopeLen
	poolTotal int64   // ugnot locked at creation (+ top-ups)
	poolLeft  int64   // remaining payable amount
	paidOut   int64   // ugnot paid to hunters so far
	refunded  int64   // ugnot refunded to the sponsor so far
	priceCrit int64   // price per tier (ugnot)
	priceHigh int64
	priceMed  int64
	priceLow  int64
	createdAt int64 // block height
	deadline  int64 // height: no new commits after this
	status    BountyStatus
	// Outcome counters (design §4: stored as counters, not derived).
	acceptedCount  int64
	duplicateCount int64
	rejectedCount  int64
	// paidTiers is the authoritative tier-once record (design §5.6):
	// bit (sev-1) is set when that severity tier has been paid for
	// this bounty. It is the ONLY enforcement that does not depend on
	// a caller-supplied findings list — see RecordPayout and
	// TierAlreadyPaid (defence-in-depth). It survives TopUp: topping
	// up the pool never re-opens a paid tier.
	paidTiers uint8
}

// ValidateNewBounty checks constructor arguments and returns "" when
// they are all valid, otherwise a human-readable reason. NewBounty
// panics with the same reason; the realm converts it into a rejected
// transaction.
func ValidateNewBounty(sponsor, arbiter address, title, scope string, priceCrit, priceHigh, priceMed, priceLow, createdAt, deadline int64) string {
	if sponsor == "" {
		return "sponsor address must not be empty"
	}
	if arbiter == "" {
		return "arbiter address must not be empty"
	}
	if len(title) == 0 || len(title) > MaxTitleLen {
		return "title must be 1-100 characters"
	}
	if len(scope) == 0 || len(scope) > MaxScopeLen {
		return "scope must be 1-1000 characters"
	}
	for _, p := range []int64{priceCrit, priceHigh, priceMed, priceLow} {
		if p < MinTierPrice {
			return "each tier price must be at least 100000 ugnot"
		}
	}
	total, ok := CheckedAdd(priceCrit, priceHigh)
	if !ok {
		return "tier prices overflow"
	}
	total, ok = CheckedAdd(total, priceMed)
	if !ok {
		return "tier prices overflow"
	}
	total, ok = CheckedAdd(total, priceLow)
	if !ok {
		return "tier prices overflow"
	}
	if total < MinBountyReward {
		return "pool total must be at least 1000000 ugnot (1 GNOT)"
	}
	if deadline < createdAt {
		return "deadline must not be before creation height"
	}
	if createdAt < 0 {
		return "creation height must not be negative"
	}
	return ""
}

// NewBounty builds a Bounty in state Open with the full pool locked.
// It panics on invalid arguments (see ValidateNewBounty).
func NewBounty(id uint64, sponsor, arbiter address, title, scope string, priceCrit, priceHigh, priceMed, priceLow, createdAt, deadline int64) Bounty {
	if msg := ValidateNewBounty(sponsor, arbiter, title, scope, priceCrit, priceHigh, priceMed, priceLow, createdAt, deadline); msg != "" {
		panic(msg)
	}
	total, _ := CheckedAdd(priceCrit, priceHigh)
	total, _ = CheckedAdd(total, priceMed)
	total, _ = CheckedAdd(total, priceLow)
	return Bounty{
		id: id, sponsor: sponsor, arbiter: arbiter,
		title: title, scope: scope,
		poolTotal: total, poolLeft: total,
		priceCrit: priceCrit, priceHigh: priceHigh,
		priceMed: priceMed, priceLow: priceLow,
		createdAt: createdAt, deadline: deadline,
		status: BountyOpen,
	}
}

// PriceFor returns the configured price of a severity tier.
func (b Bounty) PriceFor(sev Severity) int64 {
	switch sev {
	case SevCritical:
		return b.priceCrit
	case SevHigh:
		return b.priceHigh
	case SevMedium:
		return b.priceMed
	case SevLow:
		return b.priceLow
	default:
		return 0
	}
}

// CheckInvariant verifies design §4.2 invariant 1, 5 and 6 for this
// bounty and returns "" when they hold, otherwise a reason.
func (b Bounty) CheckInvariant() string {
	if !b.status.Valid() {
		return "invalid bounty status"
	}
	if b.poolLeft < 0 || b.paidOut < 0 || b.refunded < 0 || b.poolTotal < 0 {
		return "negative pool amount"
	}
	sum, ok := CheckedAdd(b.poolLeft, b.paidOut)
	if !ok {
		return "pool accounting overflow"
	}
	sum, ok = CheckedAdd(sum, b.refunded)
	if !ok {
		return "pool accounting overflow"
	}
	if sum != b.poolTotal {
		return "poolLeft + paidOut + refunded != poolTotal"
	}
	if b.deadline < b.createdAt {
		return "deadline before creation height"
	}
	return ""
}

// TierPaid reports whether a severity tier has already been paid for
// this bounty (design §5.6). Invalid severities report unpaid.
func (b Bounty) TierPaid(sev Severity) bool {
	if !sev.Valid() {
		return false
	}
	return b.paidTiers&(uint8(1)<<(uint8(sev)-1)) != 0
}

// RecordPayout moves amount from poolLeft to paidOut and returns the
// payout the realm must execute with SendCoins. Callers must move the
// finding to a final status in the same transaction (CEI: state first,
// coins second). It panics on invalid amounts, insufficient pool, or
// a tier that has already been paid — the paidTiers flag is set here,
// at the single choke point where hunter money moves, so no verdict
// path can pay a tier twice even if the caller passes a wrong or
// empty `others` list to the verdict (see TierAlreadyPaid).
func (b *Bounty) RecordPayout(to address, sev Severity, amount int64) Payout {
	if b.status != BountyOpen {
		panic("payout only from an Open bounty")
	}
	if to == "" {
		panic("payout recipient must not be empty")
	}
	if amount <= 0 {
		panic("payout amount must be positive")
	}
	if !sev.Valid() {
		panic("payout severity must be a valid tier")
	}
	if b.TierPaid(sev) {
		panic("this severity tier has already been paid for this bounty")
	}
	if amount > b.poolLeft {
		panic("payout exceeds pool left")
	}
	b.paidTiers |= uint8(1) << (uint8(sev) - 1)
	b.poolLeft -= amount
	b.paidOut += amount
	b.acceptedCount++
	return NewPayout(PayoutPayHunter, to, amount)
}

// RecordRefund moves amount from poolLeft to refunded and returns the
// payout the realm must execute. Used by Cancel/Close. It panics on
// invalid amounts or insufficient pool.
func (b *Bounty) RecordRefund(to address, amount int64) Payout {
	if b.status != BountyOpen {
		panic("refund only from an Open bounty")
	}
	if to == "" {
		panic("refund recipient must not be empty")
	}
	if amount <= 0 {
		panic("refund amount must be positive")
	}
	if amount > b.poolLeft {
		panic("refund exceeds pool left")
	}
	b.poolLeft -= amount
	b.refunded += amount
	return NewPayout(PayoutRefundSponsor, to, amount)
}

// RecordDuplicate notes an arbiter duplicate verdict (no money moves).
func (b *Bounty) RecordDuplicate() {
	b.duplicateCount++
}

// RecordRejected notes an arbiter rejection (no money moves).
func (b *Bounty) RecordRejected() {
	b.rejectedCount++
}

// Close marks the bounty Closed (final). The realm must refund the
// remaining pool first via RecordRefund; Close panics while poolLeft > 0
// so funds can never be stranded in a Closed bounty.
func (b *Bounty) Close() {
	if b.status != BountyOpen {
		panic("only an Open bounty can close")
	}
	if b.poolLeft != 0 {
		panic("cannot close with pool left; refund first")
	}
	b.status = BountyClosed
}

// Cancel marks the bounty Cancelled (final). Same refund-first rule as Close.
func (b *Bounty) Cancel() {
	if b.status != BountyOpen {
		panic("only an Open bounty can cancel")
	}
	if b.poolLeft != 0 {
		panic("cannot cancel with pool left; refund first")
	}
	b.status = BountyCancelled
}

// Getters — all return value copies.
func (b Bounty) ID() uint64            { return b.id }
func (b Bounty) Sponsor() address      { return b.sponsor }
func (b Bounty) Arbiter() address      { return b.arbiter }
func (b Bounty) Title() string         { return b.title }
func (b Bounty) Scope() string         { return b.scope }
func (b Bounty) PoolTotal() int64      { return b.poolTotal }
func (b Bounty) PoolLeft() int64       { return b.poolLeft }
func (b Bounty) PaidOut() int64        { return b.paidOut }
func (b Bounty) Refunded() int64       { return b.refunded }
func (b Bounty) PriceCrit() int64      { return b.priceCrit }
func (b Bounty) PriceHigh() int64      { return b.priceHigh }
func (b Bounty) PriceMed() int64       { return b.priceMed }
func (b Bounty) PriceLow() int64       { return b.priceLow }
func (b Bounty) CreatedAt() int64      { return b.createdAt }
func (b Bounty) Deadline() int64       { return b.deadline }
func (b Bounty) Status() BountyStatus  { return b.status }
func (b Bounty) AcceptedCount() int64  { return b.acceptedCount }
func (b Bounty) DuplicateCount() int64 { return b.duplicateCount }
func (b Bounty) RejectedCount() int64  { return b.rejectedCount }

// ---------------------------------------------------------------------------
// Finding
// ---------------------------------------------------------------------------

// Finding is one hunter's report against a bounty.
// The salt is NEVER stored: only the hunter holds it; the realm
// recomputes the commitment from the revealed fields + salt.
type Finding struct {
	id             uint64
	bountyID       uint64
	hunter         address
	severity       Severity // hunter's claim at commit; arbiter may correct it
	severityFinal  Severity // 0 until the verdict sets the final tier
	commitHash     string   // 64 lowercase hex sha256 (see §4.1)
	committedAt    int64
	revealDeadline int64  // committedAt + RevealWindow; unrevealed commits lapse
	title          string // <= MaxTitleLen, set at reveal
	pocURL         string // <= MaxPocURLLen, https://, set at reveal
	revealedAt     int64
	reviewDeadline int64 // revealedAt + ReviewWindow; arbiter must decide by this height
	status         FindingStatus
	verdictBy      address
	verdictAt      int64
	verdictReason  string // <= MaxReasonLen
	duplicateOf    uint64 // when Duplicate: id of the original finding
	paidAmount     int64  // ugnot paid (0 when not paid)
	disclosedAt    int64
	disputed       bool   // true once the hunter has disputed a rejection
	disputeReason  string // <= MaxReasonLen, set at dispute
	disputedAt     int64  // block height of the dispute; starts the
	// arbiter -> sponsor -> hunter timeout ladder for Disputed
	// findings (see DisputeReviewDeadlineAt / DisputeClaimableAfter)
}

// ValidateNewFinding checks commit-time arguments; "" means valid.
func ValidateNewFinding(hunter address, severity Severity, commitHash string, committedAt, revealDeadline int64) string {
	if hunter == "" {
		return "hunter address must not be empty"
	}
	if !severity.Valid() {
		return "invalid severity"
	}
	if msg := ValidateCommitHash(commitHash); msg != "" {
		return msg
	}
	if revealDeadline <= committedAt {
		return "reveal deadline must be after commit height"
	}
	if committedAt < 0 {
		return "commit height must not be negative"
	}
	return ""
}

// NewFinding builds a Finding in state Committed. It panics on invalid
// arguments (see ValidateNewFinding).
func NewFinding(id, bountyID uint64, hunter address, severity Severity, commitHash string, committedAt, revealDeadline int64) Finding {
	if msg := ValidateNewFinding(hunter, severity, commitHash, committedAt, revealDeadline); msg != "" {
		panic(msg)
	}
	return Finding{
		id: id, bountyID: bountyID, hunter: hunter,
		severity: severity, commitHash: commitHash,
		committedAt: committedAt, revealDeadline: revealDeadline,
		status: FindingCommitted,
	}
}

// ValidateReveal checks reveal-time arguments; "" means valid. The
// commitment itself is verified by the realm with MakeCommitment.
func ValidateReveal(title, pocURL, salt string) string {
	if len(title) == 0 || len(title) > MaxTitleLen {
		return "title must be 1-100 characters"
	}
	if len(pocURL) == 0 || len(pocURL) > MaxPocURLLen {
		return "PoC URL must be 1-300 characters"
	}
	if !strings.HasPrefix(pocURL, "https://") {
		return "PoC URL must start with https://"
	}
	if msg := ValidateSalt(salt); msg != "" {
		return msg
	}
	return ""
}

// CheckInvariant verifies design §4.2 invariant 6 for this finding.
func (f Finding) CheckInvariant() string {
	if !f.status.Valid() {
		return "invalid finding status"
	}
	if f.revealDeadline <= f.committedAt {
		return "reveal deadline must be after commit height"
	}
	if f.severityFinal != 0 && !f.severityFinal.Valid() {
		return "invalid final severity"
	}
	if f.paidAmount < 0 {
		return "negative paid amount"
	}
	if f.reviewDeadline != 0 && f.revealedAt != 0 && f.reviewDeadline <= f.revealedAt {
		return "review deadline must be after reveal height"
	}
	switch f.status {
	case FindingRevealed, FindingDisputed, FindingAccepted, FindingDuplicate, FindingRejected, FindingDisclosed:
		if f.reviewDeadline == 0 {
			return "review deadline must be set once revealed"
		}
	}
	if f.status == FindingDisputed && !f.disputed {
		return "disputed status requires a recorded dispute"
	}
	if len(f.disputeReason) > MaxReasonLen {
		return "dispute reason too long"
	}
	return ""
}

// Getters — all return value copies.
func (f Finding) ID() uint64              { return f.id }
func (f Finding) BountyID() uint64        { return f.bountyID }
func (f Finding) Hunter() address         { return f.hunter }
func (f Finding) Severity() Severity      { return f.severity }
func (f Finding) SeverityFinal() Severity { return f.severityFinal }
func (f Finding) CommitHash() string      { return f.commitHash }
func (f Finding) CommittedAt() int64      { return f.committedAt }
func (f Finding) RevealDeadline() int64   { return f.revealDeadline }
func (f Finding) Title() string           { return f.title }
func (f Finding) PocURL() string          { return f.pocURL }
func (f Finding) RevealedAt() int64       { return f.revealedAt }
func (f Finding) ReviewDeadline() int64   { return f.reviewDeadline }
func (f Finding) Status() FindingStatus   { return f.status }
func (f Finding) VerdictBy() address      { return f.verdictBy }
func (f Finding) VerdictAt() int64        { return f.verdictAt }
func (f Finding) VerdictReason() string   { return f.verdictReason }
func (f Finding) DuplicateOf() uint64     { return f.duplicateOf }
func (f Finding) PaidAmount() int64       { return f.paidAmount }
func (f Finding) DisclosedAt() int64      { return f.disclosedAt }
func (f Finding) DisputedBefore() bool    { return f.disputed }
func (f Finding) DisputeReason() string   { return f.disputeReason }
func (f Finding) DisputedAt() int64       { return f.disputedAt }

// ---------------------------------------------------------------------------
// HunterStats
// ---------------------------------------------------------------------------

// HunterStats is the public reputation record of one hunter.
// Ranking: accepted desc, earned desc, address asc (deterministic).
type HunterStats struct {
	addr       address
	submitted  int
	accepted   int
	duplicates int
	rejected   int
	earned     int64 // total ugnot received
}

// NewHunterStats builds an empty record for addr. It panics on an empty address.
func NewHunterStats(addr address) HunterStats {
	if addr == "" {
		panic("hunter address must not be empty")
	}
	return HunterStats{addr: addr}
}

// RecordSubmitted counts one new finding (any status).
func (s *HunterStats) RecordSubmitted() { s.submitted++ }

// RecordAccepted counts one paid finding and adds its payout to earned.
func (s *HunterStats) RecordAccepted(amount int64) {
	if amount < 0 {
		panic("accepted amount must not be negative")
	}
	total, ok := CheckedAdd(s.earned, amount)
	if !ok {
		panic("hunter earned overflow")
	}
	s.earned = total
	s.accepted++
}

// RecordDuplicate counts one finding marked duplicate.
func (s *HunterStats) RecordDuplicate() { s.duplicates++ }

// RecordRejected counts one rejected finding.
func (s *HunterStats) RecordRejected() { s.rejected++ }

// Getters.
func (s HunterStats) Addr() address   { return s.addr }
func (s HunterStats) Submitted() int  { return s.submitted }
func (s HunterStats) Accepted() int   { return s.accepted }
func (s HunterStats) Duplicates() int { return s.duplicates }
func (s HunterStats) Rejected() int   { return s.rejected }
func (s HunterStats) Earned() int64   { return s.earned }

// ---------------------------------------------------------------------------
// ArbiterStats
// ---------------------------------------------------------------------------

// ArbiterStats is the public track record of one arbiter.
type ArbiterStats struct {
	addr       address
	verdicts   int
	accepted   int
	rejected   int
	duplicates int
	timeouts   int // times the arbiter's verdict right expired
}

// NewArbiterStats builds an empty record for addr. It panics on an empty address.
func NewArbiterStats(addr address) ArbiterStats {
	if addr == "" {
		panic("arbiter address must not be empty")
	}
	return ArbiterStats{addr: addr}
}

// RecordVerdict counts one verdict of the given outcome.
func (s *ArbiterStats) RecordVerdict(accepted, rejected, duplicate bool) {
	s.verdicts++
	switch {
	case accepted:
		s.accepted++
	case rejected:
		s.rejected++
	case duplicate:
		s.duplicates++
	}
}

// RecordTimeout counts one expired verdict right (arbiter stayed silent).
func (s *ArbiterStats) RecordTimeout() { s.timeouts++ }

// Getters.
func (s ArbiterStats) Addr() address   { return s.addr }
func (s ArbiterStats) Verdicts() int   { return s.verdicts }
func (s ArbiterStats) Accepted() int   { return s.accepted }
func (s ArbiterStats) Rejected() int   { return s.rejected }
func (s ArbiterStats) Duplicates() int { return s.duplicates }
func (s ArbiterStats) Timeouts() int   { return s.timeouts }

// ---------------------------------------------------------------------------
// Payout
// ---------------------------------------------------------------------------

// PayoutKind says what a payout is for.
type PayoutKind uint8

const (
	// PayoutNone is the zero value: no payout is due.
	PayoutNone PayoutKind = iota
	// PayoutPayHunter pays a hunter for an accepted finding.
	PayoutPayHunter
	// PayoutRefundSponsor refunds remaining pool to the sponsor.
	PayoutRefundSponsor
)

// Payout is the single coin movement a state transition may cause.
// Guarantee (design §4): a non-zero payout is only ever returned
// together with a move to a final state, and final states refuse all
// moves — so one finding can pay out at most once.
type Payout struct {
	Kind   PayoutKind
	To     address
	Amount int64
}

// NewPayout builds a payout. It panics on an empty recipient, a
// non-positive amount, or PayoutNone with an amount.
func NewPayout(kind PayoutKind, to address, amount int64) Payout {
	if kind == PayoutNone {
		panic("payout kind must not be None")
	}
	if to == "" {
		panic("payout recipient must not be empty")
	}
	if amount <= 0 {
		panic("payout amount must be positive")
	}
	return Payout{Kind: kind, To: to, Amount: amount}
}

// Due reports whether this payout must be executed (design §4): a
// kind is set AND the amount is positive, so a hand-built struct
// literal with a kind and a zero amount is never treated as due.
func (p Payout) Due() bool { return p.Kind != PayoutNone && p.Amount > 0 }

// Package watchtower provides shared status logic for the Watchtower
// status-board realm (gno.land/r/g1vkwmdxutueeax9ys820gsv6k9qu93ftzet0t7f/watchtower).
//
// Other realms can import this package to report their own status into a
// Watchtower board, or reuse the status computation locally.
//
// NOTE (scaffold): verify import paths and stdlib surface against the
// current Gno version before deploying — see ROADMAP.md Fase 0.
package watchtower

import (
	"time"
)

// Status values for a monitored service.
const (
	StatusUnknown     = "unknown"
	StatusOperational = "operational"
	StatusDegraded    = "degraded"
	StatusDown        = "down"
	StatusMaintenance = "maintenance"
)

// Manual overrides a service owner can set. ManualNone means the status is
// derived purely from heartbeat age.
const (
	ManualNone        = ""
	ManualMaintenance = StatusMaintenance
	ManualDown        = StatusDown
)

// ComputeStatus derives a service status from its heartbeat age.
//
//   - manual override always wins (maintenance / forced down)
//   - age <= interval            -> operational
//   - age <= 3*interval          -> degraded
//   - otherwise                  -> down
//   - lastBeat == 0 (never seen) -> unknown
func ComputeStatus(lastBeatUnix int64, intervalSec int64, manual string, now time.Time) string {
	if manual == ManualMaintenance || manual == ManualDown {
		return manual
	}
	if lastBeatUnix == 0 {
		return StatusUnknown
	}
	if intervalSec <= 0 {
		intervalSec = 300 // default 5 minutes
	}
	age := now.Unix() - lastBeatUnix
	switch {
	case age <= intervalSec:
		return StatusOperational
	case age <= 3*intervalSec:
		return StatusDegraded
	default:
		return StatusDown
	}
}

// StatusMark returns a short marker used by Render() boards.
// Kept ASCII/emoji-free in the realm; the CLI adds colour for terminals.
func StatusMark(status string) string {
	switch status {
	case StatusOperational:
		return "[OK]"
	case StatusDegraded:
		return "[DEGRADED]"
	case StatusDown:
		return "[DOWN]"
	case StatusMaintenance:
		return "[MAINTENANCE]"
	default:
		return "[UNKNOWN]"
	}
}

// FormatAge renders a heartbeat age as e.g. "42s", "3m", "2h", "1d".
func FormatAge(ageSec int64) string {
	if ageSec < 0 {
		ageSec = 0
	}
	switch {
	case ageSec < 60:
		return itoa(ageSec) + "s"
	case ageSec < 3600:
		return itoa(ageSec/60) + "m"
	case ageSec < 86400:
		return itoa(ageSec/3600) + "h"
	default:
		return itoa(ageSec/86400) + "d"
	}
}

func itoa(n int64) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var buf [20]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		buf[i] = '-'
	}
	return string(buf[i:])
}

