package tavern

import (
	"chain/markdown"
	"strconv"
	"strings"
	"time"
)

// Render draws the tavern board: the running totals, the Regulars
// Board leaderboard, and the most recent guestbook signatures, newest
// first. Guestbook messages are user-supplied, so they are escaped for
// inline markdown before being written to the page.
func Render(path string) string {
	var b strings.Builder

	b.WriteString("# 🍺 Tavern Guestbook\n\n")
	b.WriteString("*A cozy corner of gno.land. Sign the guestbook, check in daily, " +
		"and earn your stool among the Regulars.*\n\n")
	b.WriteString("---\n\n")
	b.WriteString("**Guestbook signatures:** " + strconv.Itoa(totalSigns) +
		" · **Check-ins poured:** " + strconv.Itoa(totalCheckIns) +
		" · **Patrons on record:** " + strconv.Itoa(len(patrons)) +
		" · **Today:** " + formatDay(today()) + " (UTC)\n\n")

	b.WriteString("## 🏆 Regulars Board\n\n")
	if len(board) == 0 {
		b.WriteString("_No regulars yet — the first stool by the fire is yours._\n\n")
	} else {
		b.WriteString("| # | Regular | Streak (days) | Best streak | Visits |\n")
		b.WriteString("|---|---------|---------------|-------------|--------|\n")
		for i, a := range board {
			p := patrons[a]
			b.WriteString("| " + strconv.Itoa(i+1) +
				" | " + shortAddr(a) +
				" | " + strconv.Itoa(p.streak) +
				" | " + strconv.Itoa(p.best) +
				" | " + strconv.Itoa(p.total) + " |\n")
		}
		b.WriteString("\n")
	}

	b.WriteString("## 📖 Latest in the Guestbook\n\n")
	if len(book) == 0 {
		b.WriteString("_The first page is still blank. Leave the first words._\n\n")
	} else {
		for i := len(book) - 1; i >= 0; i-- {
			e := book[i]
			b.WriteString("- **" + shortAddr(e.author) + "** · " + formatDay(e.day) +
				" — " + markdown.EscapeInline(e.msg) + "\n")
		}
		b.WriteString("\n")
	}

	b.WriteString("---\n\n")
	b.WriteString("### Pull up a stool\n\n")
	b.WriteString("- **Sign the guestbook** — call `Sign` with a short message (one line, up to 140 characters).\n")
	b.WriteString("- **Check in daily** — call `CheckIn` once a day; back-to-back days build your streak.\n")
	b.WriteString("- **Climb the board** — the top 10 regulars, ranked by streak and then visits, are carved above the bar.\n")

	return b.String()
}

// formatDay renders a UTC day number as an ISO date.
func formatDay(day int64) string {
	return time.Unix(day*secondsPerDay, 0).UTC().Format("2006-01-02")
}

// Package tavern implements the Tavern Guestbook realm: a cozy social
// corner of gno.land where visitors sign a shared guestbook and check in
// once a day to build a streak and climb the Regulars Board.
//
// State is deliberately lean (on-chain storage is metered per byte):
//   - the guestbook keeps only the most recent guestbookKeep entries,
//     plus a counter of every signature ever left;
//   - each patron costs one small record (last check-in day, current
//     streak, best streak, total check-ins);
//   - the Regulars Board is a bounded slice of at most boardSize
//     addresses, re-ranked on every check-in.
package tavern

import (
	"strconv"
	"strings"
	"time"
	"unicode/utf8"
)

const (
	// maxMessageRunes caps a guestbook message at 140 characters.
	maxMessageRunes = 140
	// guestbookKeep bounds how many recent guestbook entries are stored.
	guestbookKeep = 50
	// boardSize bounds the Regulars Board.
	boardSize = 10
	// secondsPerDay converts a unix timestamp into a UTC day number.
	secondsPerDay = 86400
)

// entry is one guestbook signature.
type entry struct {
	author address
	day    int64 // UTC day number (unix seconds / 86400)
	msg    string
}

// patron is one visitor's check-in record.
type patron struct {
	lastDay int64 // UTC day number of the most recent check-in
	streak  int   // current run of consecutive daily check-ins
	best    int   // longest streak ever reached
	total   int   // lifetime check-ins
}

var (
	book          []entry
	board         []address
	patrons       = map[address]*patron{}
	totalSigns    int
	totalCheckIns int
)

// today returns the current UTC day number, derived from the block time
// (the stdlib time package reports the executing block's timestamp).
func today() int64 {
	return time.Now().Unix() / secondsPerDay
}

// Sign leaves a message in the guestbook for the calling address.
// The message must be a single line of at most 140 characters.
func Sign(cur realm, msg string) string {
	author := cur.Previous().Address()

	clean, reason := validateMessage(msg)
	if reason != "" {
		panic(reason)
	}

	book = append(book, entry{author: author, day: today(), msg: clean})
	if len(book) > guestbookKeep {
		book = book[len(book)-guestbookKeep:]
	}
	totalSigns++

	return "Signed the guestbook — you are guest #" + strconv.Itoa(totalSigns) + "."
}

// validateMessage trims a guestbook message and checks it against the
// tavern rules, returning the cleaned message, or a rejection reason.
func validateMessage(msg string) (string, string) {
	msg = strings.TrimSpace(msg)
	if msg == "" {
		return "", "tavern: message is empty"
	}
	if strings.ContainsAny(msg, "\n\r\t") {
		return "", "tavern: message must be a single line"
	}
	if utf8.RuneCountInString(msg) > maxMessageRunes {
		return "", "tavern: message is too long (max " + strconv.Itoa(maxMessageRunes) + " characters)"
	}
	return msg, ""
}

// CheckIn records a daily check-in for the calling address. Checking in
// on back-to-back days grows the streak; missing a day restarts it at 1.
// A second check-in on the same day changes nothing and simply reports
// the current standing.
func CheckIn(cur realm) string {
	return checkIn(cur.Previous().Address(), today())
}

func checkIn(who address, day int64) string {
	p := patrons[who]
	if p == nil {
		patrons[who] = &patron{lastDay: day, streak: 1, best: 1, total: 1}
		totalCheckIns++
		updateBoard(who)
		return "Welcome to the tavern, " + shortAddr(who) + "! First check-in — streak of 1 day."
	}
	if p.lastDay == day {
		return "Already checked in today, " + shortAddr(who) +
			". Streak: " + strconv.Itoa(p.streak) + " day(s), visits: " + strconv.Itoa(p.total) + "."
	}
	if p.lastDay == day-1 {
		p.streak++
	} else {
		p.streak = 1
	}
	if p.streak > p.best {
		p.best = p.streak
	}
	p.total++
	p.lastDay = day
	totalCheckIns++
	updateBoard(who)
	return "Checked in, " + shortAddr(who) + "! Streak: " + strconv.Itoa(p.streak) +
		" day(s), visits: " + strconv.Itoa(p.total) + "."
}

// ranksBefore reports whether patron a belongs ahead of patron b on the
// Regulars Board: higher streak first, then more visits, then the lower
// address (so the order is fully deterministic).
func ranksBefore(a, b address) bool {
	pa, pb := patrons[a], patrons[b]
	if pa.streak != pb.streak {
		return pa.streak > pb.streak
	}
	if pa.total != pb.total {
		return pa.total > pb.total
	}
	return a.String() < b.String()
}

// updateBoard re-inserts a patron into the Regulars Board after a
// check-in and trims the board back to boardSize entries.
func updateBoard(who address) {
	for i, a := range board {
		if a == who {
			board = append(board[:i], board[i+1:]...)
			break
		}
	}
	pos := len(board)
	for i, a := range board {
		if ranksBefore(who, a) {
			pos = i
			break
		}
	}
	board = append(board, who)
	for i := len(board) - 1; i > pos; i-- {
		board[i] = board[i-1]
	}
	board[pos] = who
	if len(board) > boardSize {
		board = board[:boardSize]
	}
}

// GuestCount returns how many guestbook signatures have ever been left.
func GuestCount() int {
	return totalSigns
}

// CheckInCount returns how many check-ins have ever been poured.
func CheckInCount() int {
	return totalCheckIns
}

// PatronStats returns the check-in record of one address:
// current streak, best streak, total check-ins, and whether the
// address has ever checked in.
func PatronStats(addr address) (streak, best, total int, ok bool) {
	p := patrons[addr]
	if p == nil {
		return 0, 0, 0, false
	}
	return p.streak, p.best, p.total, true
}

// shortAddr renders an address in a compact, human-friendly form.
func shortAddr(a address) string {
	s := a.String()
	if len(s) <= 18 {
		return s
	}
	return s[:11] + "…" + s[len(s)-5:]
}

package tavern

import (
	"chain/markdown"
	"crypto/bech32"
	"strconv"
	"strings"
	"testing"
	"time"
)

// testAddr derives a deterministic test address from a short name,
// using the same bech32 trick as the official test utilities (stdlib
// only, so the suite runs without downloading any on-chain package).
func testAddr(name string) address {
	raw := []byte("____________________")
	copy(raw[:], name)
	converted, err := bech32.ConvertBits(raw, 8, 5, true)
	if err != nil {
		panic(err)
	}
	enc, err := bech32.Encode("g", converted)
	if err != nil {
		panic(err)
	}
	return address(enc)
}

var (
	alice = testAddr("alice")
	bob   = testAddr("bob")
	carol = testAddr("carol")
	dave  = testAddr("dave")
	erin  = testAddr("erin")
	frank = testAddr("frank")
	grace = testAddr("grace")
)

// setActor makes addr the acting user and moves the block clock to the
// given UTC day number (one hour into the day).
func setActor(addr address, day int64) {
	testing.SetRealm(testing.NewUserRealm(addr))
	ctx := testing.GetContext()
	ctx.CurrentRealm = testing.NewUserRealm(addr)
	ctx.OriginCaller = addr
	ctx.Time = time.Unix(day*secondsPerDay+3600, 0)
	testing.SetContext(ctx)
}

func resetState() {
	book = nil
	board = nil
	patrons = map[address]*patron{}
	totalSigns = 0
	totalCheckIns = 0
}

func TestSignGuestbook(cur realm, t *testing.T) {
	resetState()

	setActor(alice, 100)
	res := Sign(cross(cur), "First round is on me!")
	if !strings.Contains(res, "guest #1") {
		t.Fatalf("unexpected Sign reply: %q", res)
	}
	setActor(bob, 100)
	Sign(cross(cur), "Cozy place.")
	setActor(alice, 101)
	Sign(cross(cur), "Back again.")

	if totalSigns != 3 || GuestCount() != 3 {
		t.Fatalf("totalSigns = %d, want 3", totalSigns)
	}
	if len(book) != 3 {
		t.Fatalf("len(book) = %d, want 3", len(book))
	}
	if book[0].author != alice || book[0].msg != "First round is on me!" || book[0].day != 100 {
		t.Fatalf("book[0] = %+v", book[0])
	}
	if book[2].author != alice || book[2].day != 101 {
		t.Fatalf("book[2] = %+v", book[2])
	}
	// Signing the guestbook is not a check-in.
	if totalCheckIns != 0 {
		t.Fatalf("totalCheckIns = %d, want 0", totalCheckIns)
	}
}

func TestSignRingBound(cur realm, t *testing.T) {
	resetState()
	setActor(alice, 100)

	for i := 1; i <= 55; i++ {
		Sign(cross(cur), "msg-"+pad2(i))
	}
	if totalSigns != 55 {
		t.Fatalf("totalSigns = %d, want 55", totalSigns)
	}
	if len(book) != guestbookKeep {
		t.Fatalf("len(book) = %d, want %d", len(book), guestbookKeep)
	}
	if book[0].msg != "msg-06" {
		t.Fatalf("oldest kept entry = %q, want msg-06", book[0].msg)
	}
	if book[len(book)-1].msg != "msg-55" {
		t.Fatalf("newest entry = %q, want msg-55", book[len(book)-1].msg)
	}
	out := Render("")
	// Messages are markdown-escaped in the render, so compare the
	// escaped forms: the newest entry shows, the evicted one is gone.
	if !strings.Contains(out, markdown.EscapeInline("msg-55")) ||
		strings.Contains(out, markdown.EscapeInline("msg-05")) {
		t.Fatalf("render should show msg-55 and no longer show evicted msg-05")
	}
}

func pad2(i int) string {
	if i < 10 {
		return "0" + strconv.Itoa(i)
	}
	return strconv.Itoa(i)
}

// NOTE: a panic raised inside a crossing function (Sign, CheckIn) is
// not recoverable from Gno test code — it aborts the whole test run
// (on-chain it simply reverts the transaction). The guard rules are
// therefore tested at the validateMessage layer that Sign is wired to,
// and Sign itself is exercised live on the testnet, where a rejected
// call is observable as a reverted transaction.
func TestSignGuards(cur realm, t *testing.T) {
	resetState()

	rejected := map[string]string{
		"empty message":   "",
		"blank message":   "   ",
		"newline in text": "two\nlines",
		"tab in text":     "a\tb",
		"141 ascii chars": strings.Repeat("x", 141),
		"141 runes":       strings.Repeat("é", 141),
	}
	for what, msg := range rejected {
		if _, reason := validateMessage(msg); reason == "" {
			t.Fatalf("validateMessage accepted %s", what)
		}
	}

	// Exactly at the cap — including multibyte runes — is accepted.
	for _, msg := range []string{strings.Repeat("x", 140), strings.Repeat("é", 140), "hello"} {
		if _, reason := validateMessage(msg); reason != "" {
			t.Fatalf("validateMessage rejected a valid message: %s", reason)
		}
	}

	// Sign stores the trimmed message.
	setActor(alice, 100)
	Sign(cross(cur), "  padded with care  ")
	if len(book) != 1 || book[0].msg != "padded with care" {
		t.Fatalf("stored message = %+v, want trimmed text", book)
	}
}

func TestCheckInStreaks(cur realm, t *testing.T) {
	resetState()

	setActor(alice, 200)
	res := CheckIn(cross(cur))
	if !strings.Contains(res, "First check-in") {
		t.Fatalf("unexpected first CheckIn reply: %q", res)
	}
	streak, best, total, ok := PatronStats(alice)
	if !ok || streak != 1 || best != 1 || total != 1 {
		t.Fatalf("after first check-in: streak=%d best=%d total=%d ok=%v", streak, best, total, ok)
	}

	// Same day again: a no-op that reports the standing.
	res = CheckIn(cross(cur))
	if !strings.Contains(res, "Already checked in") {
		t.Fatalf("unexpected same-day reply: %q", res)
	}
	if totalCheckIns != 1 {
		t.Fatalf("totalCheckIns = %d after same-day repeat, want 1", totalCheckIns)
	}

	setActor(alice, 201)
	CheckIn(cross(cur))
	setActor(alice, 202)
	CheckIn(cross(cur))
	streak, best, total, _ = PatronStats(alice)
	if streak != 3 || best != 3 || total != 3 {
		t.Fatalf("after 3 consecutive days: streak=%d best=%d total=%d", streak, best, total)
	}

	// Skip day 203: the streak restarts, the best is remembered.
	setActor(alice, 204)
	CheckIn(cross(cur))
	streak, best, total, _ = PatronStats(alice)
	if streak != 1 || best != 3 || total != 4 {
		t.Fatalf("after missed day: streak=%d best=%d total=%d", streak, best, total)
	}
	if totalCheckIns != 4 || CheckInCount() != 4 {
		t.Fatalf("totalCheckIns = %d, want 4", totalCheckIns)
	}

	if _, _, _, ok := PatronStats(bob); ok {
		t.Fatalf("bob never checked in but has stats")
	}
}

// checkInOn checks addr in on each of the given days. It is a
// top-level helper on purpose: a realm value must be threaded through
// explicit parameters — calling a crossing function through a closure
// that captures cur makes cur.Previous() resolve to the wrong realm.
func checkInOn(cur realm, addr address, days ...int64) {
	for _, d := range days {
		setActor(addr, d)
		CheckIn(cross(cur))
	}
}

func TestRegularsBoard(cur realm, t *testing.T) {
	resetState()

	checkInOn(cur, carol, 300, 301, 302, 303, 304) // streak 5, total 5
	checkInOn(cur, erin, 300, 301, 302, 303)       // streak 4, total 4
	checkInOn(cur, dave, 300, 301, 302)            // streak 3, total 3
	checkInOn(cur, grace, 300, 301, 303)           // streak 1, total 3
	checkInOn(cur, frank, 300)                     // streak 1, total 1

	want := []address{carol, erin, dave, grace, frank}
	if len(board) != len(want) {
		t.Fatalf("len(board) = %d, want %d (%v)", len(board), len(want), board)
	}
	for i, a := range want {
		if board[i] != a {
			t.Fatalf("board[%d] = %s, want %s (board: %v)", i, board[i], a, board)
		}
	}

	// The board is capped at boardSize even with many more patrons.
	for i := 0; i < 8; i++ {
		setActor(testAddr("guest"+strconv.Itoa(i)), 300)
		CheckIn(cross(cur))
	}
	if len(board) != boardSize {
		t.Fatalf("len(board) = %d, want cap %d", len(board), boardSize)
	}
	if board[0] != carol || board[1] != erin {
		t.Fatalf("top of board changed unexpectedly: %v", board[:2])
	}
}

func TestRender(cur realm, t *testing.T) {
	resetState()

	empty := Render("")
	if !strings.Contains(empty, "# 🍺 Tavern Guestbook") ||
		!strings.Contains(empty, "No regulars yet") ||
		!strings.Contains(empty, "first page is still blank") {
		t.Fatalf("empty render missing expected sections:\n%s", empty)
	}

	setActor(alice, 20785) // 2026-11-28
	Sign(cross(cur), "Best stew in gno.land!")
	CheckIn(cross(cur))
	setActor(alice, 20786)
	CheckIn(cross(cur))

	out := Render("")
	for _, want := range []string{
		"# 🍺 Tavern Guestbook",
		"## 🏆 Regulars Board",
		"## 📖 Latest in the Guestbook",
		markdown.EscapeInline("Best stew in gno.land!"),
		"Guestbook signatures:** 1",
		"Check-ins poured:** 2",
		"2026-11-28", // the signature's rendered ISO date
	} {
		if !strings.Contains(out, want) {
			t.Fatalf("render missing %q:\n%s", want, out)
		}
	}
}

func TestRenderEscapesMessages(cur realm, t *testing.T) {
	resetState()
	setActor(alice, 200)

	msg := "# not-a-heading *not-bold*"
	Sign(cross(cur), msg)
	out := Render("")
	if !strings.Contains(out, markdown.EscapeInline(msg)) {
		t.Fatalf("render does not contain the escaped message:\n%s", out)
	}
	if strings.Contains(out, "\n# not-a-heading") {
		t.Fatalf("raw message leaked into render as a heading:\n%s", out)
	}
}

// Package vault is the DEMO VULNERABLE realm for BugTavern (design §9.1).
//
// DO NOT USE IN PRODUCTION. It is intentionally flawed so the demo can
// show a real Critical finding end to end: deposit, drain, bounty,
// commit, reveal, verdict, payout, disclosure.
//
// The flaw (one sentence): Withdraw checks the VICTIM's balance but
// sends the coins to the CALLER without checking caller == victim —
// anyone can drain anyone else's deposit.
//
// The fix lives in the sibling package vaultfixed (a separate realm
// path): it checks caller == victim and pays the victim. It is a
// separate directory because two files defining Deposit in one package
// cannot compile; the design doc's single-directory sketch (§3.3) is
// corrected on that point — see README.
package vault

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
)

// deposits maps each depositor to their ugnot balance.
var deposits = make(map[address]int64)

// Deposit records the ugnot attached to this call under the caller.
// Only direct user calls may deposit, and the amount must be positive.
func Deposit(cur realm) {
	caller := cur.Previous().Address()
	if !cur.Previous().IsUserCall() {
		panic("deposit must be a direct user call")
	}
	amount := unsafe.OriginSend().AmountOf("ugnot")
	if amount <= 0 {
		panic("deposit amount must be positive")
	}
	deposits[caller] += amount
}

// BalanceOf returns the recorded deposit of addr (0 when none).
func BalanceOf(addr address) int64 {
	return deposits[addr]
}

// Withdraw sends amount ugnot of the VICTIM's deposit to the CALLER.
//
// VULNERABLE — INTENTIONAL: there is no check that the caller is the
// victim, and the payout goes to the caller instead of the victim.
// Anyone can call Withdraw(victim, victimBalance) and take everything.
func Withdraw(cur realm, victim address, amount int64) {
	caller := cur.Previous().Address()
	bal := deposits[victim]
	if amount <= 0 {
		panic("amount must be positive")
	}
	if amount > bal {
		panic("insufficient balance")
	}
	deposits[victim] = bal - amount
	banker.NewBanker(banker.BankerTypeRealmSend, cur).
		SendCoins(cur.Address(), caller,
			chain.NewCoins(chain.NewCoin("ugnot", amount)))
}

