// Package assertpay pays for code that passes.
//
// A spec is Go code on chain: an interface and a test suite in a frozen /p/
// package. A sponsor funds a task on a spec. A solver commits a hash with a
// bond, deploys an implementation and reveals it from a small entry realm.
// This realm runs the spec's tests against it, in the reveal transaction.
// The earliest-committed passing implementation wins, unless someone
// breaks it during the challenge window with a seed of their choice, which
// pays them the winner's bond. After the window the winner is paid.
//
// The task logic lives in the pure market package; this realm only moves
// coins and decides who may call what. There is no admin key.
package aprh1

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"crypto/sha256"
	"encoding/hex"
	"strconv"

	"gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/aprh1/check/v1"
	"gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/aprh1/market/v1"
	"gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/aprh1/specs/intervals/bad/v1"
	"gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/aprh1/specs/intervals/v1"
	lrubad "gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/aprh1/specs/lru/bad/v1"
	"gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/aprh1/specs/lru/v1"
)

const denom = "ugnot"

type specEntry struct {
	Spec      check.Spec
	Path      string // package holding the interface and tests
	Reviewed  bool   // imported statically by this realm
	Registrar string // realm that registered it (unreviewed specs)
	bad       any    // a known-bad implementation for the walletless demo
}

var (
	specs     = map[string]*specEntry{}
	specOrder []string
	tasks     []*market.Task
	running   bool
)

func init() {
	addSpec(&specEntry{Spec: intervals.Spec(), Path: "gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/aprh1/specs/intervals/v1", Reviewed: true, bad: intervals.Factory(bad.New)})
	addSpec(&specEntry{Spec: lru.Spec(), Path: "gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/aprh1/specs/lru/v1", Reviewed: true, bad: lru.Factory(lrubad.New)})
}

func addSpec(e *specEntry) {
	if _, ok := specs[e.Spec.Name]; ok {
		panic("assertpay: spec name taken")
	}
	specs[e.Spec.Name] = e
	specOrder = append(specOrder, e.Spec.Name)
}

// RegisterSpec adds a spec from another realm (usually from its init). It
// is listed as unreviewed: its test function could be realm code.
func RegisterSpec(cur realm, s check.Spec, path string) {
	guard()
	reg := cur.Previous().PkgPath()
	if reg == "" {
		panic("assertpay: RegisterSpec must be called from a realm")
	}
	if !validName(s.Name) || s.Tests == nil || len(s.Doc) > 600 || len(path) > 120 {
		panic("assertpay: bad spec")
	}
	addSpec(&specEntry{Spec: s, Path: path, Registrar: reg})
	chain.Emit("SpecRegistered", "name", s.Name, "registrar", reg)
}

func guard() {
	if running {
		panic("assertpay: re-entrant call")
	}
}

func mustUser(cur realm) address {
	guard()
	if cur.Previous().PkgPath() != "" {
		panic("assertpay: call this directly from your wallet")
	}
	return cur.Previous().Address()
}

func sent() int64 { return unsafe.OriginSend().AmountOf(denom) }

func mustTask(id int) *market.Task {
	if id < 0 || id >= len(tasks) {
		panic("assertpay: unknown task")
	}
	return tasks[id]
}

// Fund opens a task on spec with the ugnot sent as the reward. Commits are
// accepted for deadlineBlocks blocks.
func Fund(cur realm, spec string, deadlineBlocks int64) int {
	who := mustUser(cur)
	if _, ok := specs[spec]; !ok {
		panic("assertpay: unknown spec")
	}
	t := market.NewTask(len(tasks), spec, who, sent(), runtime.ChainHeight(), deadlineBlocks)
	tasks = append(tasks, t)
	chain.Emit("TaskFunded", "task", strconv.Itoa(t.ID), "spec", spec, "reward", strconv.FormatInt(t.Reward, 10))
	return t.ID
}

// HashFor is the commitment a solver must Commit before revealing from
// entry with salt. Compute it off chain or with a query.
func HashFor(task int, who address, entry, salt string) string {
	h := sha256.Sum256([]byte(strconv.Itoa(task) + "|" + who.String() + "|" + entry + "|" + salt))
	return hex.EncodeToString(h[:])
}

// Commit seals a future reveal. Send exactly the task's bond.
func Commit(cur realm, task int, hash string) {
	who := mustUser(cur)
	t := mustTask(task)
	if sent() != t.Bond {
		panic("assertpay: send exactly the bond (" + strconv.FormatInt(t.Bond, 10) + denom + ")")
	}
	if len(hash) != 64 {
		panic("assertpay: hash must be 64 hex chars")
	}
	t.AddCommit(who, hash, runtime.ChainHeight())
	chain.Emit("Committed", "task", strconv.Itoa(task), "who", who.String())
}

// SeedFor is the seed a reveal runs with: public and deterministic. A
// reveal passing one seed proves little; challenges decide.
func SeedFor(hash string, height int64) uint64 {
	d := sha256.Sum256([]byte(hash + "|" + strconv.FormatInt(height, 10)))
	var x uint64
	for i := 0; i < 8; i++ {
		x = x<<8 | uint64(d[i])
	}
	return x
}

// Reveal is called by the solver's entry realm with the implementation.
// It returns "passed/total".
func Reveal(cur realm, task int, salt string, impl any) string {
	guard()
	entry := cur.Previous().PkgPath()
	if entry == "" {
		panic("assertpay: Reveal must be called from your entry realm")
	}
	who := unsafe.OriginCaller()
	t := mustTask(task)
	now := runtime.ChainHeight()
	hash := HashFor(task, who, entry, salt)
	c := t.FindCommit(who, hash, now)
	res := runTests(t.Spec, impl, SeedFor(hash, now))
	a, pays := t.Reveal(c, entry, impl, res, now)
	pay(cur, pays)
	chain.Emit("Revealed", "task", strconv.Itoa(task), "attempt", strconv.Itoa(a.ID), "passed", strconv.Itoa(a.Passed), "total", strconv.Itoa(a.Total))
	return strconv.Itoa(a.Passed) + "/" + strconv.Itoa(a.Total)
}

// Challenge runs the current winner with your seed. If it fails, the
// winner is removed and its bond is paid to you.
func Challenge(cur realm, task int, seed uint64) string {
	who := mustUser(cur)
	t := mustTask(task)
	now := runtime.ChainHeight()
	w := t.CheckChallenge(now)
	res := runTests(t.Spec, w.Impl, seed)
	pays := t.Challenged(who, res, now)
	pay(cur, pays)
	out := "held"
	if !res.Pass() {
		out = "broke: " + res.Fail
	}
	chain.Emit("Challenged", "task", strconv.Itoa(task), "seed", strconv.FormatUint(seed, 10), "outcome", out)
	return out
}

// OpenChallenge is the two-step challenge for a winner whose code aborts
// the transaction. Send the task's bond; then anyone calls RunChallenge,
// or after the grace period TimeoutChallenge removes the winner.
func OpenChallenge(cur realm, task int, seed uint64) {
	who := mustUser(cur)
	t := mustTask(task)
	t.Open(who, seed, sent(), runtime.ChainHeight())
	chain.Emit("ChallengeOpened", "task", strconv.Itoa(task), "seed", strconv.FormatUint(seed, 10))
}

// RunChallenge runs the open challenge.
func RunChallenge(cur realm, task int) string {
	mustUser(cur)
	t := mustTask(task)
	ch := t.OpenChallenge()
	if ch == nil {
		panic("assertpay: no open challenge")
	}
	res := runTests(t.Spec, t.Attempts[ch.Target].Impl, ch.Seed)
	pay(cur, t.RanOpen(res, runtime.ChainHeight()))
	chain.Emit("ChallengeRun", "task", strconv.Itoa(task), "outcome", ch.Outcome)
	return ch.Outcome
}

// TimeoutChallenge removes a winner whose open challenge nobody could run.
func TimeoutChallenge(cur realm, task int) {
	mustUser(cur)
	t := mustTask(task)
	pay(cur, t.TimeoutOpen(runtime.ChainHeight()))
	chain.Emit("ChallengeTimeout", "task", strconv.Itoa(task))
}

// Claim pays the winner after the window. Anyone may call it.
func Claim(cur realm, task int) string {
	mustUser(cur)
	t := mustTask(task)
	pays := t.Claim(runtime.ChainHeight())
	pay(cur, pays)
	chain.Emit("Paid", "task", strconv.Itoa(task), "to", pays[0].To.String(), "amount", strconv.FormatInt(pays[0].Amount, 10))
	return "paid " + pays[0].To.String()
}

// Refund returns the reward to the sponsor after the deadline when no
// implementation passed and nothing is pending. Anyone may call it.
func Refund(cur realm, task int) {
	mustUser(cur)
	t := mustTask(task)
	pay(cur, t.Refund(runtime.ChainHeight()))
	chain.Emit("Refunded", "task", strconv.Itoa(task))
}

func runTests(spec string, impl any, seed uint64) market.Result {
	e := specs[spec]
	running = true
	rs := check.RunSpec(e.Spec, impl, seed)
	running = false
	return summarize(rs, seed)
}

func summarize(rs []check.Result, seed uint64) market.Result {
	bits := make([]byte, len(rs))
	r := market.Result{Seed: seed, Total: len(rs)}
	for i, x := range rs {
		if x.Pass {
			bits[i] = 'p'
			r.Passed++
		} else {
			bits[i] = 'f'
			if r.Fail == "" {
				msg := x.Msg
				if len(msg) > 300 {
					msg = msg[:300] + "..."
				}
				r.Fail = x.Name + ": " + msg
			}
		}
	}
	r.Bits = string(bits)
	return r
}

func pay(cur realm, pays []market.Payment) {
	if len(pays) == 0 {
		return
	}
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	for _, p := range pays {
		if p.Amount > 0 {
			b.SendCoins(cur.Address(), p.To, chain.NewCoins(chain.NewCoin(denom, p.Amount)))
		}
	}
}

func validName(s string) bool {
	if len(s) < 2 || len(s) > 24 {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '-') {
			return false
		}
	}
	return true
}

package aprh1

import (
	"chain/runtime"
	"encoding/base64"
	"strconv"
	"strings"

	"gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/aprh1/check/v1"
	"gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/aprh1/market/v1"
	"gno.land/p/moul/txlink/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
)

// self is this realm's web path, constant so links stay right when another
// realm calls Render.
const self = "/r/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/aprh1/v1"

// Render serves:
//
//	""                         home
//	"spec/<name>[?seed=N]"     a spec, with a live run of a known-bad implementation
//	"task/<id>"                a task: attempts, winner, challenges, actions
//	"json/task/<id>"           the same for agents
func Render(path string) string {
	path, query := splitQuery(path)
	parts := strings.Split(path, "/")
	switch {
	case path == "":
		return renderHome()
	case parts[0] == "spec" && len(parts) == 2:
		return renderSpec(parts[1], query)
	case parts[0] == "task" && len(parts) == 2:
		if id, err := strconv.Atoi(parts[1]); err == nil && id >= 0 && id < len(tasks) {
			return renderTask(tasks[id])
		}
	case path == "json/task" || (parts[0] == "json" && len(parts) == 3 && parts[1] == "task"):
		if len(parts) == 3 {
			if id, err := strconv.Atoi(parts[2]); err == nil && id >= 0 && id < len(tasks) {
				return taskJSON(tasks[id])
			}
		}
	}
	return "# Not found\n\n[Assertpay](" + self + ")\n"
}

func renderHome() string {
	var b strings.Builder
	b.WriteString("# Assertpay\n\n**Code that passes gets paid.** The tests are the contract, and anyone can be the auditor.\n\n")
	b.WriteString("1. A sponsor funds a task on a spec: an interface and tests, as Go code on chain.\n")
	b.WriteString("2. A solver (a person or an AI agent) reveals an implementation; this realm runs the tests in the same transaction.\n")
	b.WriteString("3. The earliest passing implementation is paid, unless someone breaks it during the window with their own seed and takes its bond.\n\n")
	b.WriteString("No reviewer, no arbiter, no admin key.\n\n## Open tasks\n\n")
	n := 0
	for i := len(tasks) - 1; i >= 0; i-- {
		t := tasks[i]
		if t.State != market.Open {
			continue
		}
		if n == 0 {
			b.WriteString("| Task | Spec | Reward | Status |\n|---|---|---|---|\n")
		}
		n++
		b.WriteString("| [#" + strconv.Itoa(t.ID) + "](" + self + ":task/" + strconv.Itoa(t.ID) + ") | " + t.Spec + " | " + gnot(t.Reward) + " | " + status(t) + " |\n")
	}
	if n == 0 {
		b.WriteString("_None right now._\n")
	}
	b.WriteString("\n## Specs\n\n")
	for _, name := range specOrder {
		e := specs[name]
		b.WriteString("- [" + name + "](" + self + ":spec/" + name + ")")
		if !e.Reviewed {
			b.WriteString(" (unreviewed)")
		}
		b.WriteString(": " + sanitize.InlineText(e.Spec.Doc) + "\n")
	}
	paid := 0
	for i := len(tasks) - 1; i >= 0 && paid < 5; i-- {
		t := tasks[i]
		if t.State == market.Paid {
			if paid == 0 {
				b.WriteString("\n## Recently paid\n\n")
			}
			paid++
			w := t.Winner()
			b.WriteString("- [#" + strconv.Itoa(t.ID) + "](" + self + ":task/" + strconv.Itoa(t.ID) + ") " + t.Spec + ": " + gnot(t.Reward) + " to " + short(w.Who) + " for [" + w.Entry + "](" + webPath(w.Entry) + "$source)\n")
		}
	}
	return b.String()
}

func renderSpec(name, query string) string {
	e, ok := specs[name]
	if !ok {
		return "# Not found\n"
	}
	seed := uint64(1)
	if v := queryValue(query, "seed"); v != "" {
		if s, err := strconv.ParseUint(v, 10, 64); err == nil {
			seed = s
		}
	}
	var b strings.Builder
	b.WriteString("# Spec: " + name + "\n\n" + sanitize.InlineText(e.Spec.Doc) + "\n\n")
	if e.Reviewed {
		b.WriteString("Reviewed: imported by this realm. ")
	} else {
		b.WriteString("**Unreviewed**: registered by [" + e.Registrar + "](" + webPath(e.Registrar) + "$source); read it first. ")
	}
	b.WriteString("Interface and tests: [" + e.Path + "](" + webPath(e.Path) + "$source)\n\n")
	if e.bad != nil {
		rs := check.RunSpec(e.Spec, e.bad, seed)
		r := summarize(rs, seed)
		b.WriteString("## Try it: a plausible but wrong implementation, seed " + strconv.FormatUint(seed, 10) + "\n\n")
		b.WriteString(matrix(r.Bits) + "\n\n")
		b.WriteString(strconv.Itoa(r.Passed) + " of " + strconv.Itoa(r.Total) + " tests pass. ")
		if r.Fail != "" {
			b.WriteString("First counterexample:\n\n> " + sanitize.InlineText(r.Fail) + "\n\n")
		} else {
			b.WriteString("**It passes this seed.** That is why a reveal is not the end: during the window anyone can try another seed and take the bond.\n\n")
		}
		b.WriteString("Seeds: ")
		for _, s := range []uint64{seed + 1, seed + 2, seed*7 + 3, seed + 1000} {
			b.WriteString("[" + strconv.FormatUint(s, 10) + "](" + self + ":spec/" + name + "?seed=" + strconv.FormatUint(s, 10) + ") ")
		}
		b.WriteString("\n\nEvery square is one test: the first are fixed examples, the rest are generated from the seed. Change the seed in the URL; no wallet needed.\n\n")
	}
	b.WriteString("## Fund a task on this spec\n\n[Fund 10 GNOT, 2000 blocks](" + txlink.Realm("gno.land"+self).Call("Fund", "spec", name, "deadlineBlocks", "2000") + ") (set the amount in your wallet)\n")
	return b.String()
}

func renderTask(t *market.Task) string {
	now := runtime.ChainHeight()
	id := strconv.Itoa(t.ID)
	var b strings.Builder
	b.WriteString("# Task #" + id + ": " + t.Spec + "\n\n")
	b.WriteString("- Reward: **" + gnot(t.Reward) + "** from " + short(t.Sponsor) + "\n")
	b.WriteString("- Bond per commit: " + gnot(t.Bond) + " (back on reveal if you fail; kept by the winner; paid to whoever breaks the winner)\n")
	b.WriteString("- Status: " + status(t) + "\n")
	b.WriteString("- Commits close at block " + strconv.FormatInt(t.Deadline, 10) + " (now " + strconv.FormatInt(now, 10) + ")\n")
	b.WriteString("- Spec: [" + t.Spec + "](" + self + ":spec/" + t.Spec + ")\n\n")
	if w := t.Winner(); w != nil {
		b.WriteString("## Current winner\n\n[" + w.Entry + "](" + webPath(w.Entry) + "$source) by " + short(w.Who) + ", committed at block " + strconv.FormatInt(w.CommitH, 10) + ". ")
		if t.State == market.Open {
			if now <= t.WindowEnd {
				b.WriteString("Challenge window open until block " + strconv.FormatInt(t.WindowEnd, 10) + ": [break it with your seed](" + txlink.Realm("gno.land"+self).Call("Challenge", "task", id, "seed", "") + ").\n\n")
			} else {
				b.WriteString("Window over: [claim](" + txlink.Realm("gno.land"+self).Call("Claim", "task", id) + ").\n\n")
			}
		} else {
			b.WriteString("Paid.\n\n")
		}
	}
	if len(t.Attempts) > 0 {
		b.WriteString("## Attempts\n\n")
		for i := len(t.Attempts) - 1; i >= 0; i-- {
			a := t.Attempts[i]
			b.WriteString("**#" + strconv.Itoa(a.ID) + "** [" + a.Entry + "](" + webPath(a.Entry) + "$source) by " + short(a.Who) + ", commit " + strconv.FormatInt(a.CommitH, 10) + ", seed " + strconv.FormatUint(a.Seed, 10) + ": " + strconv.Itoa(a.Passed) + "/" + strconv.Itoa(a.Total))
			if a.Removed {
				b.WriteString(" (broken by a challenge)")
			}
			b.WriteString("\n\n" + matrix(a.Bits) + "\n\n")
			if a.Fail != "" {
				b.WriteString("> " + sanitize.InlineText(a.Fail) + "\n\n")
			}
		}
	}
	if len(t.Challenges) > 0 {
		b.WriteString("## Challenges\n\n| By | Target | Seed | Outcome |\n|---|---|---|---|\n")
		for _, c := range t.Challenges {
			out := c.Outcome
			if c.Open {
				out = "open"
			}
			if c.Fail != "" {
				out += ": " + sanitize.TableCell(c.Fail)
			}
			b.WriteString("| " + short(c.Who) + " | #" + strconv.Itoa(c.Target) + " | " + strconv.FormatUint(c.Seed, 10) + " | " + out + " |\n")
		}
		b.WriteString("\n")
	}
	live := 0
	for _, c := range t.Commits {
		if c.Live(now) {
			live++
		}
	}
	b.WriteString("## Solve it\n\n" + strconv.Itoa(live) + " live commit(s) now. Forfeited bonds so far: " + gnot(t.Forfeit) + ".\n\n")
	b.WriteString("1. Pick an entry realm path you control and a secret salt; get your hash: `HashFor(" + id + ", <your address>, <entry path>, <salt>)`.\n")
	b.WriteString("2. Commit it with the bond: [Commit](" + txlink.Realm("gno.land"+self).Call("Commit", "task", id, "hash", "") + ") (send " + strconv.FormatInt(t.Bond, 10) + "ugnot).\n")
	b.WriteString("3. Deploy your implementation as a /p/ package and an entry realm that calls `assertpay.Reveal(cross(cur), " + id + ", salt, impl)`; call it within " + strconv.Itoa(market.Expiry) + " blocks.\n")
	return b.String()
}

func taskJSON(t *market.Task) string {
	s := "{\"id\":" + strconv.Itoa(t.ID) + ",\"spec\":\"" + t.Spec + "\",\"reward\":" + strconv.FormatInt(t.Reward, 10) + ",\"bond\":" + strconv.FormatInt(t.Bond, 10) + ",\"state\":\"" + t.State + "\",\"deadline\":" + strconv.FormatInt(t.Deadline, 10) + ",\"window_end\":" + strconv.FormatInt(t.WindowEnd, 10) + ",\"winner\":" + strconv.Itoa(t.WinnerID) + ",\"attempts\":["
	for i, a := range t.Attempts {
		if i > 0 {
			s += ","
		}
		s += "{\"id\":" + strconv.Itoa(a.ID) + ",\"entry\":\"" + a.Entry + "\",\"who\":\"" + a.Who.String() + "\",\"passed\":" + strconv.Itoa(a.Passed) + ",\"total\":" + strconv.Itoa(a.Total) + ",\"bits\":\"" + a.Bits + "\",\"removed\":" + strconv.FormatBool(a.Removed) + "}"
	}
	return s + "]}"
}

func status(t *market.Task) string {
	switch t.State {
	case market.Paid:
		return "paid"
	case market.Refunded:
		return "refunded"
	}
	now := runtime.ChainHeight()
	if w := t.Winner(); w != nil {
		if now <= t.WindowEnd {
			return "passing, challenge window open"
		}
		return "passing, claimable"
	}
	if now > t.Deadline {
		return "closed for commits"
	}
	return "open"
}

// matrix draws one square per test result: green pass, red fail.
func matrix(bits string) string {
	const size, gap, perRow = 14, 4, 10
	rows := (len(bits) + perRow - 1) / perRow
	w := perRow*(size+gap) - gap
	h := rows*(size+gap) - gap
	var b strings.Builder
	b.WriteString(`<svg xmlns="http://www.w3.org/2000/svg" width="` + strconv.Itoa(w*2) + `" height="` + strconv.Itoa(h*2) + `" viewBox="0 0 ` + strconv.Itoa(w) + ` ` + strconv.Itoa(h) + `">`)
	for i := 0; i < len(bits); i++ {
		x := (i % perRow) * (size + gap)
		y := (i / perRow) * (size + gap)
		col := "#2fb36b"
		if bits[i] != 'p' {
			col = "#e5484d"
		}
		b.WriteString(`<rect x="` + strconv.Itoa(x) + `" y="` + strconv.Itoa(y) + `" width="` + strconv.Itoa(size) + `" height="` + strconv.Itoa(size) + `" rx="3" fill="` + col + `"/>`)
	}
	b.WriteString("</svg>")
	return "![test results](data:image/svg+xml;base64," + base64.StdEncoding.EncodeToString([]byte(b.String())) + ")"
}

func gnot(u int64) string {
	whole := u / 1_000_000
	frac := u % 1_000_000
	if frac == 0 {
		return strconv.FormatInt(whole, 10) + " GNOT"
	}
	f := strconv.FormatInt(frac+1_000_000, 10)[1:]
	return strconv.FormatInt(whole, 10) + "." + strings.TrimRight(f, "0") + " GNOT"
}

func short(a address) string {
	s := a.String()
	if len(s) > 12 {
		return s[:7] + "..." + s[len(s)-4:]
	}
	return s
}

func webPath(pkg string) string { return strings.TrimPrefix(pkg, "gno.land") }

func splitQuery(path string) (string, string) {
	if i := strings.Index(path, "?"); i >= 0 {
		return path[:i], path[i+1:]
	}
	return path, ""
}

func queryValue(q, key string) string {
	for _, kv := range strings.Split(q, "&") {
		if strings.HasPrefix(kv, key+"=") {
			return kv[len(key)+1:]
		}
	}
	return ""
}

// Package good is a correct lru implementation (reference for tests).
package lrugood

import "gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/aprh1/specs/lru/v1"

type cache struct {
	cap   int
	order []string
	vals  map[string]int
}

// New returns an empty cache.
func New(capacity int) lru.Cache { return &cache{cap: capacity, vals: map[string]int{}} }

func (c *cache) touch(k string) {
	out := c.order[:0:0]
	for _, x := range c.order {
		if x != k {
			out = append(out, x)
		}
	}
	c.order = append(out, k)
}

func (c *cache) Get(k string) (int, bool) {
	v, ok := c.vals[k]
	if ok {
		c.touch(k)
	}
	return v, ok
}

func (c *cache) Put(k string, v int) {
	if _, ok := c.vals[k]; !ok && len(c.order) == c.cap {
		delete(c.vals, c.order[0])
		c.order = c.order[1:]
	}
	c.vals[k] = v
	c.touch(k)
}

func (c *cache) Len() int { return len(c.order) }

