		"| Verdict by | " + verdictByCell(f) + " |\n" +
		"| Verdict at | " + heightText(f.VerdictAt()) + " |\n" +
		"| Verdict reason | " + escCell(f.VerdictReason()) + " |\n" +
		"| Duplicate of | " + dupOf + " |\n" +
		"| Paid | " + fmtGNOT(f.PaidAmount()) + " GNOT |\n" +
		"| Disclosed | " + heightText(f.DisclosedAt()) + " |\n\n"
