// Realm streak is an on-chain habit streak tracker.
//
// Anyone can call CheckIn once per day. Checking in on consecutive
// days grows your current streak; missing a day restarts the current
// streak at 1, but your best (longest) streak and your lifetime
// check-in count are kept forever. Render shows a public leaderboard
// and per-user pages, so the whole game is readable on gnoweb with no
// frontend at all.
//
// All of the arithmetic lives in the pure package
// gno.land/p/g1hlch3c6amthkydsvlm84yk8vpzs2c7puc22wtk/streakcalc; this realm is only storage, caller
// authentication, the block clock, and rendering.
package streak

import (
	"strconv"
	"time"

	"gno.land/p/g1hlch3c6amthkydsvlm84yk8vpzs2c7puc22wtk/streakcalc"
)

// records holds one streakcalc.State per user address. It is the
// realm's entire persistent state, together with members.
var records = map[address]streakcalc.State{}

// members lists every address that has ever checked in, in
// first-check-in order. Render copies and sorts it, so leaderboard
// ordering never mutates storage.
var members []address

// CheckIn records today's check-in for the caller and returns a
// human-readable summary. It must be called directly by the user:
// a check-in forwarded through another realm would credit that
// realm's address, so cross-realm calls are rejected.
func CheckIn(cur realm) string {
	if !cur.Previous().IsUserCall() {
		panic("streak: CheckIn must be called directly by a user")
	}
	caller := cur.Previous().Address()
	day := streakcalc.DayOf(time.Now().Unix())
	before, had := records[caller]
	after := checkIn(caller, day)
	if had && after.Total == before.Total {
		return "Already checked in today. Current streak: " +
			strconv.FormatInt(after.Current, 10) + " day(s), best " +
			strconv.FormatInt(after.Longest, 10) + "."
	}
	return "Checked in. Current streak: " +
		strconv.FormatInt(after.Current, 10) + " day(s), best " +
		strconv.FormatInt(after.Longest, 10) + ", total check-in days " +
		strconv.FormatInt(after.Total, 10) + "."
}

// checkIn folds one check-in for addr on the given day index into the
// stored record and returns the updated state. It is split out of
// CheckIn so tests can drive arbitrary day sequences without a chain.
func checkIn(addr address, day int64) streakcalc.State {
	prev, ok := records[addr]
	if !ok {
		members = append(members, addr)
	}
	next := streakcalc.Apply(prev, day)
	records[addr] = next
	return next
}

// GetStats returns the stored counters for addr. found is false when
// the address has never checked in.
func GetStats(addr address) (current, longest, total, lastDay int64, found bool) {
	st, ok := records[addr]
	return st.Current, st.Longest, st.Total, st.LastDay, ok
}

// TotalUsers returns how many addresses have ever checked in.
func TotalUsers() int {
	return len(members)
}

// entry is one leaderboard row: an address and its record.
type entry struct {
	addr  address
	state streakcalc.State
}

// better reports whether entry a ranks above entry b: longest streak
// first, then current streak, then total check-in days, then the
// address itself so the order is fully deterministic.
func better(a, b entry) bool {
	if a.state.Longest != b.state.Longest {
		return a.state.Longest > b.state.Longest
	}
	if a.state.Current != b.state.Current {
		return a.state.Current > b.state.Current
	}
	if a.state.Total != b.state.Total {
		return a.state.Total > b.state.Total
	}
	return a.addr.String() < b.addr.String()
}

// top returns at most n leaderboard entries, best first.
func top(n int) []entry {
	entries := make([]entry, 0, len(members))
	for _, addr := range members {
		entries = append(entries, entry{addr: addr, state: records[addr]})
	}
	// Selection sort: only the first n positions need to be final.
	if len(entries) < n {
		n = len(entries)
	}
	for i := 0; i < n; i++ {
		best := i
		for j := i + 1; j < len(entries); j++ {
			if better(entries[j], entries[best]) {
				best = j
			}
		}
		entries[i], entries[best] = entries[best], entries[i]
	}
	return entries[:n]
}

// Render renders the realm's public pages as markdown:
//
//	""            -> the leaderboard (top 10)
//	"<address>"   -> that user's streak page
//
// Any other path gets an explanation. Only bech32 addresses and
// numbers are ever rendered, never free-form input.
func Render(path string) string {
	if path == "" {
		return renderLeaderboard()
	}
	addr := address(path)
	if _, ok := records[addr]; ok {
		return renderUser(addr)
	}
	return "# Streak\n\nNo check-ins yet for `" + path + "`.\n\n" +
		"Check in with `CheckIn` to start a streak, or open the " +
		"leaderboard at the realm's root path."
}

func renderLeaderboard() string {
	out := "# Streak — daily check-in leaderboard\n\n"
	out += "Check in once a day to grow your streak. Miss a day and " +
		"the current streak restarts at 1 — your best streak is kept forever.\n\n"
	if len(members) == 0 {
		return out + "Nobody has checked in yet. Be the first.\n"
	}
	out += "| # | User | Best streak | Current streak | Check-in days |\n"
	out += "|---|------|-------------|----------------|---------------|\n"
	for i, e := range top(10) {
		out += "| " + strconv.Itoa(i+1) +
			" | " + e.addr.String() +
			" | " + strconv.FormatInt(e.state.Longest, 10) +
			" | " + strconv.FormatInt(e.state.Current, 10) +
			" | " + strconv.FormatInt(e.state.Total, 10) + " |\n"
	}
	out += "\n" + strconv.Itoa(len(members)) + " user(s) have checked in.\n"
	return out
}

func renderUser(addr address) string {
	st := records[addr]
	out := "# Streak of " + addr.String() + "\n\n"
	out += "- Current streak: **" + strconv.FormatInt(st.Current, 10) + "** day(s)\n"
	out += "- Best streak: **" + strconv.FormatInt(st.Longest, 10) + "** day(s)\n"
	out += "- Total check-in days: **" + strconv.FormatInt(st.Total, 10) + "**\n"
	out += "- Last check-in day index: " + strconv.FormatInt(st.LastDay, 10) + "\n"
	return out
}

package streak

import (
	"strings"
	"testing"
	"time"

	"gno.land/p/g1hlch3c6amthkydsvlm84yk8vpzs2c7puc22wtk/streakcalc"
)

// Test addresses (valid bech32, taken from the gno examples).
var (
	alice = address("g1g3lsfxhvaqgdv4ccemwpnms4fv6t3aq3p5z6u7")
	bob   = address("g1juz2yxmdsa6audkp6ep9vfv80c8p5u76e03vvh")
	carol = address("g1sp8v98h2gadm5jggtzz9w5ksexqn68ympsd68h")
	dave  = address("g1vuch2um9wf047h6lta047h6lta047h6l2ewm6w")
)

// reset clears all realm state so each test starts empty.
func reset() {
	records = map[address]streakcalc.State{}
	members = nil
}

func wantStats(t *testing.T, addr address, current, longest, total, lastDay int64) {
	t.Helper()
	c, l, tot, last, found := GetStats(addr)
	if !found {
		t.Fatalf("no record for %s", addr)
	}
	if c != current || l != longest || tot != total || last != lastDay {
		t.Fatalf("%s: got (current %d, longest %d, total %d, last %d), want (%d, %d, %d, %d)",
			addr, c, l, tot, last, current, longest, total, lastDay)
	}
}

func TestFirstCheckIn(t *testing.T) {
	reset()
	st := checkIn(alice, 100)
	if st != (streakcalc.State{Current: 1, Longest: 1, Total: 1, LastDay: 100, Has: true}) {
		t.Fatalf("unexpected state: %+v", st)
	}
	wantStats(t, alice, 1, 1, 1, 100)
	if TotalUsers() != 1 {
		t.Fatalf("TotalUsers = %d, want 1", TotalUsers())
	}
}

func TestSameDayRepeat(t *testing.T) {
	reset()
	checkIn(alice, 100)
	checkIn(alice, 100)
	checkIn(alice, 100)
	wantStats(t, alice, 1, 1, 1, 100)
	if TotalUsers() != 1 {
		t.Fatalf("TotalUsers = %d, want 1", TotalUsers())
	}
}

func TestConsecutiveDays(t *testing.T) {
	reset()
	checkIn(alice, 100)
	checkIn(alice, 101)
	checkIn(alice, 102)
	wantStats(t, alice, 3, 3, 3, 102)
}

func TestGapResets(t *testing.T) {
	reset()
	checkIn(alice, 100)
	checkIn(alice, 101)
	checkIn(alice, 110) // 8 days missed
	wantStats(t, alice, 1, 2, 3, 110)
}

func TestLongestTracked(t *testing.T) {
	reset()
	for d := int64(0); d < 7; d++ {
		checkIn(alice, d)
	}
	checkIn(alice, 100) // reset after a gap
	checkIn(alice, 101)
	wantStats(t, alice, 2, 7, 9, 101)
}

func TestMultipleUsersIndependent(t *testing.T) {
	reset()
	checkIn(alice, 100)
	checkIn(alice, 101)
	checkIn(bob, 101)
	checkIn(carol, 99)
	checkIn(carol, 100)
	checkIn(carol, 101)
	wantStats(t, alice, 2, 2, 2, 101)
	wantStats(t, bob, 1, 1, 1, 101)
	wantStats(t, carol, 3, 3, 3, 101)
	if TotalUsers() != 3 {
		t.Fatalf("TotalUsers = %d, want 3", TotalUsers())
	}
	if _, _, _, _, found := GetStats(dave); found {
		t.Fatal("unknown address should have no record")
	}
}

// carol has the best streak (5); alice and bob tie on longest (3),
// and alice wins the tie on current streak (3 vs bob's 1 after a gap).
func seedLeaderboard() {
	reset()
	for d := int64(0); d < 5; d++ {
		checkIn(carol, d)
	}
	for d := int64(0); d < 3; d++ {
		checkIn(alice, d)
	}
	for d := int64(0); d < 3; d++ {
		checkIn(bob, d)
	}
	checkIn(bob, 50) // gap: bob's current drops to 1, longest stays 3
}

func TestLeaderboardOrder(t *testing.T) {
	seedLeaderboard()
	rows := top(10)
	if len(rows) != 3 {
		t.Fatalf("top(10) returned %d rows, want 3", len(rows))
	}
	if rows[0].addr != carol || rows[1].addr != alice || rows[2].addr != bob {
		t.Fatalf("order = %s, %s, %s; want carol, alice, bob",
			rows[0].addr, rows[1].addr, rows[2].addr)
	}
	if got := top(2); len(got) != 2 || got[1].addr != alice {
		t.Fatalf("top(2) wrong: %+v", got)
	}
}

func TestRenderLeaderboard(t *testing.T) {
	reset()
	if out := Render(""); !strings.Contains(out, "Nobody has checked in yet") {
		t.Fatalf("empty leaderboard render missing placeholder:\n%s", out)
	}
	seedLeaderboard()
	out := Render("")
	for _, want := range []string{
		"# Streak", carol.String(), alice.String(), bob.String(), "3 user(s)",
	} {
		if !strings.Contains(out, want) {
			t.Errorf("leaderboard render missing %q:\n%s", want, out)
		}
	}
	// Carol (best streak) must appear before alice and bob.
	ci, ai, bi := strings.Index(out, carol.String()),
		strings.Index(out, alice.String()), strings.Index(out, bob.String())
	if !(ci < ai && ai < bi) {
		t.Errorf("leaderboard rows out of order:\n%s", out)
	}
}

func TestRenderUser(t *testing.T) {
	reset()
	checkIn(alice, 100)
	checkIn(alice, 101)
	out := Render(alice.String())
	for _, want := range []string{alice.String(), "**2**", "Last check-in day index: 101"} {
		if !strings.Contains(out, want) {
			t.Errorf("user render missing %q:\n%s", want, out)
		}
	}
	if out := Render(bob.String()); !strings.Contains(out, "No check-ins yet") {
		t.Errorf("unknown user render should say no check-ins:\n%s", out)
	}
}

// TestCheckInEndToEnd drives the real crossing entry point: the
// caller is a test user realm, and a second immediate call is a
// same-day no-op whatever the test clock says.
func TestCheckInEndToEnd(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	msg := CheckIn(cross(cur))
	if !strings.Contains(msg, "Checked in") {
		t.Fatalf("first CheckIn message: %q", msg)
	}
	wantStats(t, alice, 1, 1, 1, streakcalc.DayOf(time.Now().Unix()))
	msg = CheckIn(cross(cur))
	if !strings.Contains(msg, "Already checked in today") {
		t.Fatalf("second CheckIn message: %q", msg)
	}
	if _, _, total, _, _ := GetStats(alice); total != 1 {
		t.Fatalf("total after same-day repeat = %d, want 1", total)
	}
}

package verdict3

import (
	"chain/runtime"
	"chain/runtime/unsafe"
	"math/overflow"
)

func Bet(cur realm, marketID uint64, yes bool) {
	assertDirectUserCall(cur)
	runtime.AssertOriginCall()
	placeBet(cur, marketID, yes)
}

// Keep validation separate: the pinned test runtime counts helper frames around AssertOriginCall.
func placeBet(cur realm, marketID uint64, yes bool) {
	market, ok := marketByID(marketID)
	if !ok {
		panic("market not found")
	}
	assertOpenBeforeClose(market)

	// The VM credits OriginSend before execution; Bet must not collect it again.
	amount := requireSinglePositiveUgnot()
	bettor := cur.Previous().Address()
	position, _ := positionByIDAndAddress(marketID, bettor)
	assertPoolAdditionSafe(market, yes, amount)
	assertPositionAdditionSafe(position, yes, amount)
	assertActivityIDSafe(market)

	market.NextActivityID++
	applyBetToPositionAndPool(market, bettor, yes, amount)
	appendActivity(market, bettor, yes, amount)
}

func assertDirectUserCall(cur realm) {
	requireDirectUserCall(0, cur)
}

func assertOpenBeforeClose(market Market) {
	switch market.Status {
	case MarketOpen:
	case MarketResolved:
		panic("market closed")
	default:
		panic("unknown market status")
	}
	if runtime.ChainHeight() >= market.CloseHeight {
		panic("market closed")
	}
}

func requireSinglePositiveUgnot() int64 {
	coins := unsafe.OriginSend()
	if len(coins) != 1 || coins[0].Denom != "ugnot" || coins[0].Amount <= 0 {
		panic("invalid attached stake")
	}
	return coins[0].Amount
}

func assertPoolAdditionSafe(market Market, yes bool, amount int64) {
	combinedPool, ok := overflow.Add64(market.YesPool, market.NoPool)
	if !ok {
		panic("pool overflow")
	}
	if _, ok := overflow.Add64(combinedPool, amount); !ok {
		panic("pool overflow")
	}
	selectedPool := market.NoPool
	if yes {
		selectedPool = market.YesPool
	}
	if _, ok := overflow.Add64(selectedPool, amount); !ok {
		panic("pool overflow")
	}
}

func assertPositionAdditionSafe(position Position, yes bool, amount int64) {
	selectedStake := position.NoStake
	if yes {
		selectedStake = position.YesStake
	}
	if _, ok := overflow.Add64(selectedStake, amount); !ok {
		panic("position overflow")
	}
}

func assertActivityIDSafe(market Market) {
	if market.NextActivityID == ^uint64(0) {
		panic("activity ID overflow")
	}
}

func applyBetToPositionAndPool(market Market, bettor address, yes bool, amount int64) {
	position, _ := positionByIDAndAddress(market.ID, bettor)
	if yes {
		market.YesPool += amount
		position.YesStake += amount
	} else {
		market.NoPool += amount
		position.NoStake += amount
	}
	markets.Set(marketKey(market.ID), market)
	positions.Set(positionKey(market.ID, bettor), position)
}

func appendActivity(market Market, bettor address, yes bool, amount int64) {
	activity := Activity{
		ID:       market.NextActivityID,
		MarketID: market.ID,
		Bettor:   bettor,
		Side:     yes,
		Stake:    amount,
		Height:   runtime.ChainHeight(),
	}
	activities.Set(activityKey(market.ID, activity.ID), activity)
}

