func TestStateStoresAndReturnsValueCopies(t *testing.T) {
	resetCreationState()

	market := Market{
		ID:          7,
		Question:    testQuestion,
		Creator:     testAddress,
		CloseHeight: 123,
		YesPool:     11,
		NoPool:      12,
